  struct vs_audio_stream_s s;
  pthread_mutex_t lock;
  pthread_t thread;
  bool     thread_valid;

  /* Staging ring between the TTS producer and the DAC. */

  unsigned char *ring;
  size_t   ring_size;
  size_t   head;
  size_t   tail;
  size_t   level;
  bool     ring_psram;

  /* Buffers owned by us rather than by the driver. */

