         * fine but not JSON, and each of those has a different fix.
         */

        syslog(LOG_ERR, "[%s] Failed to parse API JSON, %zu bytes: %.200s\n",
            TAG, rb.len, rb.data ? rb.data : "(null)");
        resp_buf_free(&rb);
