/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <fcntl.h>
#include <time.h>
#include <sched.h>
#include <assert.h>
#include <errno.h>
#include <debug.h>
#include <syslog.h>

#include <sys/param.h>

#include <nuttx/clock.h>
#include <nuttx/kthread.h>
#include <nuttx/spinlock.h>
#include <nuttx/wqueue.h>
#include <nuttx/net/bluetooth.h>
#include <nuttx/wireless/bluetooth/bt_core.h>
#include <nuttx/wireless/bluetooth/bt_hci.h>

#include "bt_queue.h"
#include "bt_buf.h"
#include "bt_keys.h"
#include "bt_conn.h"
#include "bt_l2cap.h"
#include "bt_hcicore.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Wait up to 2.5 seconds for a response.  This delay is arbitrary and
 * intended only to avoid hangs while waiting for a response.  It may need
 * to be adjusted.
 */

#define TIMEOUT_MSEC   2500

/****************************************************************************
 * Public Data
 ****************************************************************************/

/* State of connected HCI device.
 *
 * NOTE:  Because this is a global singleton, multiple HCI devices may not
 * be supported.
 */

struct bt_dev_s g_btdev;

/****************************************************************************
 * Private Data
 ****************************************************************************/

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
static FAR struct bt_conn_cb_s *g_callback_list;
static bt_le_scan_cb_t *g_scan_dev_found_cb;
#else
static struct bt_hci_cb_s *g_hci_cb;
#endif

/* Lists of pending received messages.  One for low priority input that is
 * processed on the low priority work queue and one for high priority
 * input that is processed on high priority work queue.
 */

static FAR struct bt_bufferlist_s g_lp_rxlist;
static FAR struct bt_bufferlist_s g_hp_rxlist;

/* Work structures: One for high priority and one for low priority work */

static struct work_s g_lp_work;
static struct work_s g_hp_work;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bt_enqueue_bufwork
 *
 * Description:
 *   Add the provided buffer 'buf' to the head selected buffer list 'list'
 *
 * Input Parameters:
 *   list - The buffer list to use
 *   buf  - The buffer to be added to the head of the buffer list
 *
 * Returned Value:
 *
 ****************************************************************************/

static void bt_enqueue_bufwork(FAR struct bt_bufferlist_s *list,
                               FAR struct bt_buf_s *buf)
{
  irqstate_t flags;

  flags      = spin_lock_irqsave(&list->lock);
  buf->flink = list->head;
  if (list->head == NULL)
    {
      list->tail = buf;
    }

  list->head = buf;
  spin_unlock_irqrestore(&list->lock, flags);
}

/****************************************************************************
 * Name: bt_dequeue_bufwork
 *
 * Description:
 *   Remove and return the buffer at the tail of the buffer list specified
 *   by 'list'.
 *
 * Input Parameters:
 *   list - The buffer list to use
 *
 * Returned Value:
 *   A pointer to the buffer that was at the tail of the buffer list.  NULL
 *   is returned if the list was empty.
 *
 ****************************************************************************/

static FAR struct bt_buf_s *
  bt_dequeue_bufwork(FAR struct bt_bufferlist_s *list)
{
  FAR struct bt_buf_s *buf;
  irqstate_t flags;

  flags = spin_lock_irqsave(&list->lock);
  buf   = list->tail;
  if (buf != NULL)
    {
      if (list->head == list->tail)
        {
          list->head = NULL;
          list->tail = NULL;
        }
      else
        {
          FAR struct bt_buf_s *prev;

          for (prev = list->head;
               prev && prev->flink != buf;
               prev = prev->flink)
            {
            }

          if (prev != NULL)
            {
              prev->flink = NULL;
              list->tail  = prev;
            }
        }

      buf->flink = NULL;
    }

  spin_unlock_irqrestore(&list->lock, flags);
  return buf;
}

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
static void bt_connected(FAR struct bt_conn_s *conn)
{
  FAR struct bt_conn_cb_s *cb;

  for (cb = g_callback_list; cb; cb = cb->flink)
    {
      if (cb->connected)
        {
          cb->connected(conn, cb->context);
        }
    }
}

static void bt_disconnected(FAR struct bt_conn_s *conn)
{
  FAR struct bt_conn_cb_s *cb;

  for (cb = g_callback_list; cb; cb = cb->flink)
    {
      if (cb->disconnected)
        {
          cb->disconnected(conn, cb->context);
        }
    }
}

static void hci_acl(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_acl_hdr_s *hdr = (FAR void *)buf->data;
  FAR struct bt_conn_s *conn;
  uint16_t handle;
  uint16_t len = BT_LE162HOST(hdr->len);
  uint8_t flags;

  wlinfo("buf %p\n", buf);

  handle            = BT_LE162HOST(hdr->handle);
  flags             = (handle >> 12);
  buf->u.acl.handle = bt_acl_handle(handle);

  bt_buf_consume(buf, sizeof(*hdr));

  wlinfo("handle %u len %u flags %u\n", buf->u.acl.handle, len, flags);

  if (buf->len != len)
    {
      wlerr("ERROR:  ACL data length mismatch (%u != %u)\n",
             buf->len, len);
      return;
    }

  conn = bt_conn_lookup_handle(buf->u.acl.handle);
  if (!conn)
    {
      wlerr("ERROR:  Unable to find conn for handle %u\n",
            buf->u.acl.handle);
      return;
    }

  bt_buf_addref(buf);
  bt_conn_receive(conn, buf, flags);
  bt_conn_release(conn);
}

/* HCI event processing */

static void hci_encrypt_change(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_encrypt_change_s *evt = (FAR void *)buf->data;
  FAR struct bt_conn_s *conn;
  uint16_t handle = BT_LE162HOST(evt->handle);

  wlinfo("status %u handle %u encrypt 0x%02x\n",
        evt->status, handle, evt->encrypt);

  if (evt->status)
    {
      return;
    }

  conn = bt_conn_lookup_handle(handle);
  if (!conn)
    {
      wlerr("ERROR:  Unable to look up conn with handle %u\n", handle);
      return;
    }

  conn->encrypt = evt->encrypt;

  bt_l2cap_encrypt_change(conn);
  bt_conn_release(conn);
}

static void hci_reset_complete(FAR struct bt_buf_s *buf)
{
  uint8_t status = buf->data[0];

  wlinfo("status %u\n", status);

  if (status)
    {
      return;
    }

  g_scan_dev_found_cb = NULL;
  g_btdev.scan_enable = BT_LE_SCAN_DISABLE;
  g_btdev.scan_filter = BT_LE_SCAN_FILTER_DUP_ENABLE;
}

static void hci_cmd_done(uint16_t opcode, uint8_t status,
                         FAR struct bt_buf_s *buf)
{
  FAR struct bt_buf_s *sent = g_btdev.sent_cmd;

  if (sent == NULL)
    {
      return;
    }

  if (g_btdev.sent_cmd == NULL)
    {
      wlerr("ERROR: Request cmd missing!\n");
      return;
    }

  if (g_btdev.sent_cmd->u.hci.opcode != opcode)
    {
      wlerr("ERROR:  Unexpected completion of opcode 0x%04x "
            "expected 0x%04x\n",
            opcode, g_btdev.sent_cmd->u.hci.opcode);
      return;
    }

  g_btdev.sent_cmd = NULL;

  if (status != 0)
    {
      syslog(LOG_ERR,
             "[BT] HCI cmd opcode 0x%04x rejected, status 0x%02x %s\n",
             sent->u.hci.opcode, status,
             (sent->u.hci.sync != NULL) ? "(sync)" : "(async)");
    }

  /* If the command was synchronous wake up bt_hci_cmd_send_sync() */

  if (sent->u.hci.sync != NULL)
    {
      FAR sem_t *sem = sent->u.hci.sync;

      if (status != 0)
        {
          sent->u.hci.sync = NULL;
        }
      else
        {
          sent->u.hci.sync = bt_buf_addref(buf);
        }

      nxsem_post(sem);
    }

  bt_buf_release(sent);
}

static void hci_cmd_complete(FAR struct bt_buf_s *buf)
{
  FAR struct hci_evt_cmd_complete_s *evt = (FAR void *)buf->data;
  uint16_t opcode = BT_LE162HOST(evt->opcode);
  FAR uint8_t *status;

  wlinfo("opcode %04x\n", opcode);

  bt_buf_consume(buf, sizeof(*evt));

  /* All command return parameters have a 1-byte status in the beginning, so
   * we can safely make this generalization.
   */

  status = buf->data;

  switch (opcode)
    {
      case BT_HCI_OP_RESET:
        hci_reset_complete(buf);
        break;

      default:
        wlinfo("Unhandled opcode %04x\n", opcode);
        break;
    }

  hci_cmd_done(opcode, *status, buf);

  if (evt->ncmd > 0 && g_btdev.ncmd == 0)
    {
      /* Allow next command to be sent */

      g_btdev.ncmd = 1;
      nxsem_post(&g_btdev.ncmd_sem);
    }
}

static void hci_cmd_status(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_cmd_status_s *evt = (FAR void *)buf->data;
  uint16_t opcode = BT_LE162HOST(evt->opcode);

  wlinfo("opcode %04x\n", opcode);

  bt_buf_consume(buf, sizeof(*evt));

  switch (opcode)
    {
      default:
        wlinfo("Unhandled opcode %04x\n", opcode);
        break;
    }

  hci_cmd_done(opcode, evt->status, buf);

  if (evt->ncmd && !g_btdev.ncmd)
    {
      /* Allow next command to be sent */

      g_btdev.ncmd = 1;
      nxsem_post(&g_btdev.ncmd_sem);
    }
}

static void hci_num_completed_packets(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_num_completed_packets_s *evt = (FAR void *)buf->data;
  uint16_t num_handles = BT_LE162HOST(evt->num_handles);
  uint16_t i;

  wlinfo("num_handles %u\n", num_handles);

  for (i = 0; i < num_handles; i++)
    {
      uint16_t handle;
      uint16_t count;

      handle = BT_LE162HOST(evt->h[i].handle);
      count  = BT_LE162HOST(evt->h[i].count);

      wlinfo("handle %u count %u\n", handle, count);
      UNUSED(handle);

      while (count--)
        {
          nxsem_post(&g_btdev.le_pkts_sem);
        }
    }
}

static void hci_encrypt_key_refresh_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_encrypt_key_refresh_complete_s *evt =
    (FAR void *)buf->data;
  FAR struct bt_conn_s *conn;
  uint16_t handle;

  handle = BT_LE162HOST(evt->handle);

  wlinfo("status %u handle %u\n", evt->status, handle);

  if (evt->status)
    {
      return;
    }

  conn = bt_conn_lookup_handle(handle);
  if (!conn)
    {
      wlerr("ERROR:  Unable to look up conn with handle %u\n", handle);
      return;
    }

  bt_l2cap_encrypt_change(conn);
  bt_conn_release(conn);
}

static void copy_id_addr(FAR struct bt_conn_s *conn,
                         FAR const bt_addr_le_t *addr)
{
  FAR struct bt_keys_s *keys;

  /* If we have a keys struct we already know the identity */

  if (conn->keys)
    {
      return;
    }

  keys = bt_keys_find_irk(addr);
  if (keys)
    {
      bt_addr_le_copy(&conn->dst, &keys->addr);
      conn->keys = keys;
    }
  else
    {
      bt_addr_le_copy(&conn->dst, addr);
    }
}

static int bt_hci_start_scanning(uint8_t scan_type, uint8_t scan_filter)
{
  FAR struct bt_buf_s *buf;
  FAR struct bt_buf_s *rsp;
  FAR struct bt_hci_cp_le_set_scan_params_s *set_param;
  FAR struct bt_hci_cp_le_set_scan_enable_s *scan_enable;
  int ret;

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_SCAN_PARAMS, sizeof(*set_param));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  set_param = bt_buf_extend(buf, sizeof(*set_param));
  memset(set_param, 0, sizeof(*set_param));
  set_param->scan_type = scan_type;

  /* for the rest parameters apply default values according to spec 4.2,
   * vol2, part E, 7.8.10
   */

  set_param->interval      = BT_HOST2LE16(0x0010);
  set_param->window        = BT_HOST2LE16(0x0010);
  set_param->filter_policy = 0x00;
  set_param->addr_type     = 0x00;

  bt_hci_cmd_send(BT_HCI_OP_LE_SET_SCAN_PARAMS, buf);
  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_SCAN_ENABLE,
                          sizeof(*scan_enable));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  scan_enable             = bt_buf_extend(buf, sizeof(*scan_enable));
  memset(scan_enable, 0, sizeof(*scan_enable));
  scan_enable->filter_dup = scan_filter;
  scan_enable->enable     = BT_LE_SCAN_ENABLE;

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_LE_SET_SCAN_ENABLE, buf, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR:  bt_hci_cmd_send_sync failed: %d\n", ret);
      return ret;
    }

  /* Update scan state in case of success (0) status */

  ret = rsp->data[0];
  if (!ret)
    {
      g_btdev.scan_enable = BT_LE_SCAN_ENABLE;
    }

  bt_buf_release(rsp);
  return ret;
}

static int bt_hci_stop_scanning(void)
{
  FAR struct bt_buf_s *buf;
  FAR struct bt_buf_s *rsp;
  FAR struct bt_hci_cp_le_set_scan_enable_s *scan_enable;
  int ret;

  if (g_btdev.scan_enable == BT_LE_SCAN_DISABLE)
    {
      wlwarn("WARNING:  Scan already disabled\n");
      return -EALREADY;
    }

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_SCAN_ENABLE,
                          sizeof(*scan_enable));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  scan_enable             = bt_buf_extend(buf, sizeof(*scan_enable));
  memset(scan_enable, 0x0, sizeof(*scan_enable));
  scan_enable->filter_dup = 0x00;
  scan_enable->enable     = BT_LE_SCAN_DISABLE;

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_LE_SET_SCAN_ENABLE, buf, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR:  bt_hci_cmd_send_sync failed: %d\n", ret);
      return ret;
    }

  /* Update scan state in case of success (0) status */

  ret = rsp->data[0];
  if (!ret)
    {
      g_btdev.scan_enable = BT_LE_SCAN_DISABLE;
    }

  bt_buf_release(rsp);
  return ret;
}

static int hci_le_create_conn(FAR const bt_addr_le_t *addr)
{
  FAR struct bt_buf_s *buf;
  FAR struct bt_hci_cp_le_create_conn_s *cp;

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_CREATE_CONN, sizeof(*cp));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  cp                      = bt_buf_extend(buf, sizeof(*cp));
  memset(cp, 0x0, sizeof(*cp));
  bt_addr_le_copy(&cp->peer_addr, addr);
  cp->conn_interval_max   = BT_HOST2LE16(0x0028);
  cp->conn_interval_min   = BT_HOST2LE16(0x0018);
  cp->scan_interval       = BT_HOST2LE16(0x0060);
  cp->scan_window         = BT_HOST2LE16(0x0030);
  cp->supervision_timeout = BT_HOST2LE16(0x07d0);

  return bt_hci_cmd_send_sync(BT_HCI_OP_LE_CREATE_CONN, buf, NULL);
}

static void hci_disconn_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_disconn_complete_s *evt = (FAR void *)buf->data;
  uint16_t handle = BT_LE162HOST(evt->handle);
  FAR struct bt_conn_s *conn;

  wlinfo("status %u handle %u reason %u\n",
         evt->status, handle, evt->reason);

  if (evt->status)
    {
      return;
    }

  conn = bt_conn_lookup_handle(handle);
  if (!conn)
    {
      wlerr("ERROR:  Unable to look up conn with handle %u\n", handle);
      return;
    }

  bt_l2cap_disconnected(conn);
  bt_disconnected(conn);

  bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
  conn->handle = 0;

  if (bt_atomic_testbit(conn->flags, BT_CONN_AUTO_CONNECT))
    {
      bt_conn_set_state(conn, BT_CONN_CONNECT_SCAN);
      bt_le_scan_update();
    }

  bt_conn_release(conn);

  if (g_btdev.adv_enable)
    {
      buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_ENABLE, 1);
      if (buf)
        {
          memcpy(bt_buf_extend(buf, 1), &g_btdev.adv_enable, 1);
          bt_hci_cmd_send(BT_HCI_OP_LE_SET_ADV_ENABLE, buf);
        }
    }
}

static void le_conn_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_le_conn_complete_s *evt = (FAR void *)buf->data;
  uint16_t handle = BT_LE162HOST(evt->handle);
  FAR struct bt_conn_s *conn;
  FAR struct bt_keys_s *keys;

  syslog(LOG_ERR,
         "[BT] LE_CONN_COMPLETE: status=0x%02x handle=%u role=%u peer=%s\n",
         evt->status, handle, evt->role, bt_addr_le_str(&evt->peer_addr));

  /* Make lookup to check if there's a connection object in CONNECT state
   * associated with passed peer LE address.
   */

  keys = bt_keys_find_irk(&evt->peer_addr);
  if (keys)
    {
      conn = bt_conn_lookup_state(&keys->addr, BT_CONN_CONNECT);
    }
  else
    {
      conn = bt_conn_lookup_state(&evt->peer_addr, BT_CONN_CONNECT);
    }

  if (evt->status)
    {
      if (!conn)
        {
          return;
        }

      bt_conn_set_state(conn, BT_CONN_DISCONNECTED);

      /* Drop the reference got by lookup call in CONNECT state. We are now
       * in the DISCONNECTED state since no successful LE link been made.
       */

      bt_conn_release(conn);
      return;
    }

  if (!conn)
    {
      conn = bt_conn_add(&evt->peer_addr, evt->role);
    }

  if (!conn)
    {
      wlerr("ERROR:  Unable to add new conn for handle %u\n", handle);
      return;
    }

  conn->handle           = handle;
  conn->src.type         = BT_ADDR_LE_PUBLIC;
  memcpy(conn->src.val, g_btdev.bdaddr.val, sizeof(g_btdev.bdaddr.val));
  copy_id_addr(conn, &evt->peer_addr);
  conn->le_conn_interval = BT_LE162HOST(evt->interval);

  bt_conn_set_state(conn, BT_CONN_CONNECTED);

  bt_l2cap_connected(conn);

  bt_connected(conn);
  bt_conn_release(conn);
  bt_le_scan_update();
}

static void check_pending_conn(FAR const bt_addr_le_t *addr, uint8_t evtype,
                               FAR struct bt_keys_s *keys)
{
  FAR struct bt_conn_s *conn;

  /* Return if event is not connectible */

  if (evtype != BT_LE_ADV_IND && evtype != BT_LE_ADV_DIRECT_IND)
    {
      return;
    }

  if (keys)
    {
      conn = bt_conn_lookup_state(&keys->addr, BT_CONN_CONNECT_SCAN);
    }
  else
    {
      conn = bt_conn_lookup_state(addr, BT_CONN_CONNECT_SCAN);
    }

  if (!conn)
    {
      return;
    }

  if (bt_hci_stop_scanning())
    {
      goto done;
    }

  if (hci_le_create_conn(addr))
    {
      goto done;
    }

  bt_conn_set_state(conn, BT_CONN_CONNECT);

done:
  bt_conn_release(conn);
}

static void le_adv_report(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_ev_le_advertising_report_s *info;
  uint8_t num_reports = buf->data[0];

  wlinfo("Adv number of reports %u\n", num_reports);

  info = bt_buf_consume(buf, sizeof(num_reports));

  while (num_reports--)
    {
      int8_t rssi = info->data[info->length];
      FAR struct bt_keys_s *keys;
      bt_addr_le_t addr;

      wlinfo("%s event %u, len %u, rssi %d dBm\n",
             bt_addr_le_str(&info->addr), info->evt_type, info->length,
             rssi);

      keys = bt_keys_find_irk(&info->addr);
      if (keys)
        {
          bt_addr_le_copy(&addr, &keys->addr);
          wlinfo("Identity %s matched RPA %s\n",
                 bt_addr_le_str(&keys->addr), bt_addr_le_str(&info->addr));
        }
      else
        {
          bt_addr_le_copy(&addr, &info->addr);
        }

      if (g_scan_dev_found_cb)
        {
          g_scan_dev_found_cb(&addr, rssi, info->evt_type,
                            info->data, info->length);
        }

      check_pending_conn(&info->addr, info->evt_type, keys);

      /* Get next report iteration by moving pointer to right offset in buf
       * according to spec 4.2, Vol 2, Part E, 7.7.65.2.
       *
       * TODO: multiple reports are stored as multiple arrays not one array
       * of structs. If num_reports > 0 this will not WORK!
       */

      /* Note that info already contains one byte which accounts for RSSI */

      info = bt_buf_consume(buf, sizeof(*info) + info->length);
    }
}

static void le_ltk_request(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_le_ltk_request_s *evt = (FAR void *)buf->data;
  FAR struct bt_conn_s *conn;
  uint16_t handle;

  handle = BT_LE162HOST(evt->handle);

  wlinfo("handle %u\n", handle);

  conn = bt_conn_lookup_handle(handle);
  if (!conn)
    {
      wlerr("ERROR:  Unable to lookup conn for handle %u\n", handle);
      return;
    }

  if (!conn->keys)
    {
      conn->keys = bt_keys_find(BT_KEYS_SLAVE_LTK, &conn->dst);
    }

  if (conn->keys && (conn->keys->keys & BT_KEYS_SLAVE_LTK) &&
      conn->keys->slave_ltk.rand == evt->rand &&
      conn->keys->slave_ltk.ediv == evt->ediv)
    {
      FAR struct bt_hci_cp_le_ltk_req_reply_s *cp;

      buf = bt_hci_cmd_create(BT_HCI_OP_LE_LTK_REQ_REPLY, sizeof(*cp));
      if (!buf)
        {
          wlerr("ERROR:  Out of command buffers\n");
          goto done;
        }

      cp         = bt_buf_extend(buf, sizeof(*cp));
      cp->handle = evt->handle;
      memcpy(cp->ltk, conn->keys->slave_ltk.val, 16);

      bt_hci_cmd_send(BT_HCI_OP_LE_LTK_REQ_REPLY, buf);
    }
  else
    {
      FAR struct bt_hci_cp_le_ltk_req_neg_reply_s *cp;

      buf = bt_hci_cmd_create(BT_HCI_OP_LE_LTK_REQ_NEG_REPLY, sizeof(*cp));
      if (!buf)
        {
          wlerr("ERROR:  Out of command buffers\n");
          goto done;
        }

      cp         = bt_buf_extend(buf, sizeof(*cp));
      cp->handle = evt->handle;

      bt_hci_cmd_send(BT_HCI_OP_LE_LTK_REQ_NEG_REPLY, buf);
    }

done:
  bt_conn_release(conn);
}

static int le_param_request(FAR struct bt_buf_s *buf)
{
  FAR struct bt_buf_s *reply_buf;
  FAR struct bt_hci_cp_le_rem_conn_param_req_reply_s *params_reply;
  FAR struct bt_hci_evt_le_rem_conn_param_req_s *params_request;

  reply_buf = bt_hci_cmd_create(BT_HCI_OP_LE_REM_CONN_PARAM_REQ_RPLY,
                sizeof(*params_reply));
  if (!reply_buf)
    {
      return -ENOBUFS;
    }

  params_request = (FAR void *)buf->data;

  params_reply = bt_buf_extend(reply_buf, sizeof(*params_reply));
  memset(params_reply, 0, sizeof(*params_reply));
  params_reply->handle = BT_HOST2LE16(params_request->handle);
  params_reply->min_interval = BT_HOST2LE16(params_request->min_interval);
  params_reply->max_interval = BT_HOST2LE16(params_request->max_interval);
  params_reply->latency = BT_HOST2LE16(params_request->latency);
  params_reply->timeout = BT_HOST2LE16(params_request->timeout);
  params_reply->max_ce_len = BT_HOST2LE16(0xffff);

  return bt_hci_cmd_send_sync(BT_HCI_OP_LE_REM_CONN_PARAM_REQ_RPLY,
          reply_buf, NULL);
}

static void hci_le_meta_event(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_le_meta_event_s *evt = (FAR void *)buf->data;

  bt_buf_consume(buf, sizeof(*evt));

  switch (evt->subevent)
    {
      case BT_HCI_EVT_LE_CONN_COMPLETE:
        le_conn_complete(buf);
        break;

      case BT_HCI_EVT_LE_ADVERTISING_REPORT:
        le_adv_report(buf);
        break;

      case BT_HCI_EVT_LE_CONN_UPDATE_COMPLETE:
        break;

      case BT_HCI_EVT_LE_LTK_REQUEST:
        le_ltk_request(buf);
        break;

      case BT_HCI_EVT_LE_CONN_PARAM_REQ:
        le_param_request(buf);
        break;

      default:
        wlinfo("Unhandled LE event %04x\n", evt->subevent);
        break;
    }
}

static void hci_event(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_evt_hdr_s *hdr = (FAR void *)buf->data;

  wlinfo("event %u\n", hdr->evt);

  bt_buf_consume(buf, sizeof(struct bt_hci_evt_hdr_s));

  switch (hdr->evt)
    {
      case BT_HCI_EVT_DISCONN_COMPLETE:
        hci_disconn_complete(buf);
        break;

      case BT_HCI_EVT_ENCRYPT_CHANGE:
        hci_encrypt_change(buf);
        break;

      case BT_HCI_EVT_ENCRYPT_KEY_REFRESH_COMPLETE:
        hci_encrypt_key_refresh_complete(buf);
        break;

      case BT_HCI_EVT_LE_META_EVENT:
        hci_le_meta_event(buf);
        break;

      default:
        wlwarn("WARNING:  Unhandled event 0x%02x\n", hdr->evt);
        break;
    }
}
#endif

/****************************************************************************
 * Name: hci_tx_kthread
 *
 * Description:
 *   This is a kernel thread that handles sending of commands.
 *
 * Input Parameters:
 *   Standard kernel thread arguments
 *
 * Returned Value:
 *   Doesn't normally return.
 *
 ****************************************************************************/

static int hci_tx_kthread(int argc, FAR char *argv[])
{
  FAR struct bt_driver_s *btdev = g_btdev.btdev;
  int ret;

  wlinfo("started\n");

  for (; g_btdev.tx_status == OK; )
    {
      FAR struct bt_buf_s *buf;

      /* Wait until ncmd > 0 */

      ret = nxsem_wait_uninterruptible(&g_btdev.ncmd_sem);
      if (ret < 0)
        {
          wlerr("nxsem_wait_uninterruptible() failed: %d\n", ret);
          return EXIT_FAILURE;
        }

      /* Get next command - wait if necessary */

      buf = NULL;
      ret = bt_queue_receive(&g_btdev.tx_queue, &buf);
      DEBUGASSERT(ret >= 0 && buf != NULL);
      UNUSED(ret);

      g_btdev.ncmd = 0;

      /* Clear out any existing sent command */

      if (g_btdev.sent_cmd)
        {
          wlerr("ERROR:  Uncleared pending sent_cmd\n");
          bt_buf_release(g_btdev.sent_cmd);
          g_btdev.sent_cmd = NULL;
        }

      /* Allow transmission if module is connected. */

      if (g_btdev.tx_status == OK)
        {
          g_btdev.sent_cmd = bt_buf_addref(buf);

          wlinfo("Sending command %04x buf %p to driver\n",
                 buf->u.hci.opcode, buf);

          bt_send(btdev, buf);
        }

      bt_buf_release(buf);
    }

  /* Acknowledge the termination request. */

  g_btdev.tx_status = ESHUTDOWN;
  return EXIT_SUCCESS;
}

/****************************************************************************
 * Name: hci_rx_work
 *
 * Description:
 *   This work function operates on the low priority work queue using the
 *   low priority buffer queue.
 *
 * Input Parameters:
 *   arg - Indicates which buffer queue should be used
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void hci_rx_work(FAR void *arg)
{
  FAR struct bt_bufferlist_s *list = (FAR struct bt_bufferlist_s *)arg;
  FAR struct bt_buf_s *buf;

  wlinfo("list %p\n", list);
  DEBUGASSERT(list != NULL);

  while ((buf = bt_dequeue_bufwork(list)) != NULL)
    {
      wlinfo("buf %p type %u len %u\n", buf, buf->type, buf->len);

      /* TODO: Hook monitor callback */

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
      switch (buf->type)
        {
          case BT_ACL_IN:
            hci_acl(buf);
            break;

          case BT_EVT:
            hci_event(buf);
            break;

          default:
            wlerr("ERROR:  Unknown buf type %u\n", buf->type);
            break;
        }
#else
      g_hci_cb->received(buf, g_hci_cb->context);
#endif
      bt_buf_release(buf);
    }
}

/****************************************************************************
 * Name: priority_rx_work
 *
 * Description:
 *   This work function operates on the high priority work thread using the
 *   high priority buffer queue.
 *
 * Input Parameters:
 *   arg - Indicates which buffer queue should be used
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void priority_rx_work(FAR void *arg)
{
  FAR struct bt_bufferlist_s *list = (FAR struct bt_bufferlist_s *)arg;
  FAR struct bt_buf_s *buf;

  wlinfo("list %p\n", list);
  DEBUGASSERT(list != NULL);

  while ((buf = bt_dequeue_bufwork(list)) != NULL)
    {
      FAR struct bt_hci_evt_hdr_s *hdr = (FAR void *)buf->data;

      wlinfo("buf %p type %u len %u\n", buf, buf->type, buf->len);

      /* TODO: Hook monitor callback */

      if (buf->type != BT_EVT)
        {
          wlerr("Unknown buf type %u\n", buf->type);
          bt_buf_release(buf);
          continue;
        }

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
      bt_buf_consume(buf, sizeof(struct bt_hci_evt_hdr_s));

      switch (hdr->evt)
        {
          case BT_HCI_EVT_CMD_COMPLETE:
            hci_cmd_complete(buf);
            break;

          case BT_HCI_EVT_CMD_STATUS:
            hci_cmd_status(buf);
            break;

          case BT_HCI_EVT_NUM_COMPLETED_PACKETS:
            hci_num_completed_packets(buf);
            break;

          default:
            wlerr("Unknown event 0x%02x\n", hdr->evt);
            break;
        }
#else
      UNUSED(hdr);

      g_hci_cb->received(buf, g_hci_cb->context);
#endif
      bt_buf_release(buf);
    }
}

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
static void read_local_features_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_rp_read_local_features_s *rp = (FAR void *)buf->data;

  wlinfo("status %u\n", rp->status);

  memcpy(g_btdev.features, rp->features, sizeof(g_btdev.features));
}

static void read_local_ver_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_rp_read_local_version_info_s *rp = (FAR void *)buf->data;

  wlinfo("status %u\n", rp->status);

  g_btdev.hci_version  = rp->hci_version;
  g_btdev.hci_revision = BT_LE162HOST(rp->hci_revision);
  g_btdev.manufacturer = BT_LE162HOST(rp->manufacturer);
}

static void read_bdaddr_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_rp_read_bd_addr_s *rp = (FAR void *)buf->data;

  wlinfo("status %u\n", rp->status);

  bt_addr_copy(&g_btdev.bdaddr, &rp->bdaddr);
}

static void read_le_features_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_rp_le_read_local_features_s *rp = (FAR void *)buf->data;

  wlinfo("status %u\n", rp->status);

  memcpy(g_btdev.le_features, rp->features, sizeof(g_btdev.le_features));
}

static void read_buffer_size_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_rp_read_buffer_size_s *rp = (FAR void *)buf->data;

  wlinfo("status %u\n", rp->status);

  /* If LE-side has buffers we can ignore the BR/EDR values */

  if (g_btdev.le_mtu)
    {
      return;
    }

  g_btdev.le_mtu  = BT_LE162HOST(rp->acl_max_len);
  g_btdev.le_pkts = BT_LE162HOST(rp->acl_max_num);
}

static void le_read_buffer_size_complete(FAR struct bt_buf_s *buf)
{
  FAR struct bt_hci_rp_le_read_buffer_size_s *rp = (FAR void *)buf->data;

  wlinfo("status %u\n", rp->status);

  g_btdev.le_mtu  = BT_LE162HOST(rp->le_max_len);
  g_btdev.le_pkts = rp->le_max_num;
}

/****************************************************************************
 * Name: hci_initialize()
 *
 * Description:
 *
 * Input Parameters:
 *   none
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static int hci_initialize(void)
{
  FAR struct bt_hci_cp_host_buffer_size_s *hbs;
  FAR struct bt_hci_cp_set_event_mask_s *ev;
  FAR struct bt_buf_s *buf;
  FAR struct bt_buf_s *rsp;
  FAR uint8_t *enable;
  int ret;

  /* Send HCI_RESET */

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_RESET, NULL, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR: BT_HCI_OP_RESET failed: %d\n", ret);
      return ret;
    }

  bt_buf_release(rsp);

  /* Read Local Supported Features */

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_READ_LOCAL_FEATURES, NULL, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR: BT_HCI_OP_READ_LOCAL_FEATURES failed: %d\n", ret);
      return ret;
    }

  read_local_features_complete(rsp);
  bt_buf_release(rsp);

  /* Read Local Version Information */

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_READ_LOCAL_VERSION_INFO, NULL, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR:  bt_hci_cmd_send_sync failed: %d\n", ret);
      return ret;
    }

  read_local_ver_complete(rsp);
  bt_buf_release(rsp);

  /* Read Bluetooth Address */

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_READ_BD_ADDR, NULL, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR:  bt_hci_cmd_send_sync failed: %d\n", ret);
      return ret;
    }

  read_bdaddr_complete(rsp);
  bt_buf_release(rsp);

  /* For now we only support LE capable controllers */

  if (!lmp_le_capable(g_btdev))
    {
      wlerr("ERROR:  Non-LE capable controller detected!\n");
      return -ENODEV;
    }

  /* Read Low Energy Supported Features */

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_LE_READ_LOCAL_FEATURES, NULL, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR:  BT_HCI_OP_LE_READ_LOCAL_FEATURES failed: %d\n", ret);
      return ret;
    }

  read_le_features_complete(rsp);
  bt_buf_release(rsp);

  /* Read LE Buffer Size */

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_LE_READ_BUFFER_SIZE, NULL, &rsp);
  if (ret < 0)
    {
      wlerr("ERROR:  BT_HCI_OP_LE_READ_BUFFER_SIZE failed: %d\n", ret);
      return ret;
    }

  le_read_buffer_size_complete(rsp);
  bt_buf_release(rsp);

  buf = bt_hci_cmd_create(BT_HCI_OP_SET_EVENT_MASK, sizeof(*ev));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  ev = bt_buf_extend(buf, sizeof(*ev));
  memset(ev, 0, sizeof(*ev));

  ev->events[0] |= 0x04;        /* Connection Complete */
  ev->events[0] |= 0x08;        /* Connection Request */
  ev->events[0] |= 0x10;        /* Disconnection Complete */
  ev->events[1] |= 0x08;        /* Read Remote Version Information Complete */
  ev->events[1] |= 0x20;        /* Command Complete */
  ev->events[1] |= 0x40;        /* Command Status */
  ev->events[1] |= 0x80;        /* Hardware Error */
  ev->events[2] |= 0x04;        /* Number of Completed Packets */
  ev->events[3] |= 0x02;        /* Data Buffer Overflow */
  ev->events[7] |= 0x20;        /* LE Meta-Event */

  if (g_btdev.le_features[0] & BT_HCI_LE_ENCRYPTION)
    {
      ev->events[0] |= 0x80;    /* Encryption Change */
      ev->events[5] |= 0x80;    /* Encryption Key Refresh Complete */
    }

  bt_hci_cmd_send_sync(BT_HCI_OP_SET_EVENT_MASK, buf, NULL);

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_EVENT_MASK, sizeof(*ev));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  ev = bt_buf_extend(buf, sizeof(*ev));
  memset(ev, 0, sizeof(*ev));

  ev->events[0] |= 0xff;

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_LE_SET_EVENT_MASK, buf, NULL);
  if (ret < 0)
    {
      wlerr("ERROR:  bt_hci_cmd_send_sync failed: %d\n", ret);
      return ret;
    }

  buf = bt_hci_cmd_create(BT_HCI_OP_HOST_BUFFER_SIZE, sizeof(*hbs));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  hbs = bt_buf_extend(buf, sizeof(*hbs));
  memset(hbs, 0, sizeof(*hbs));
  hbs->acl_mtu = BT_HOST2LE16(BLUETOOTH_MAX_FRAMELEN -
                              sizeof(struct bt_hci_acl_hdr_s) -
                              g_btdev.btdev->head_reserve);
  hbs->acl_pkts = BT_HOST2LE16(CONFIG_BLUETOOTH_BUFFER_PREALLOC);

  ret = bt_hci_cmd_send(BT_HCI_OP_HOST_BUFFER_SIZE, buf);
  if (ret < 0)
    {
      wlerr("ERROR:  bt_hci_cmd_send failed: %d\n", ret);
      return ret;
    }

  buf = bt_hci_cmd_create(BT_HCI_OP_SET_CTL_TO_HOST_FLOW, 1);
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  enable  = bt_buf_extend(buf, sizeof(*enable));
#ifdef CONFIG_BLUETOOTH_CNTRL_HOST_FLOW_DISABLE
  *enable = 0;
#else
  *enable = 1;
#endif

  ret = bt_hci_cmd_send_sync(BT_HCI_OP_SET_CTL_TO_HOST_FLOW, buf, NULL);
  if (ret < 0)
    {
      /* Some controllers (e.g. ESP32-S3 Bluedroid) don't support
       * SET_CTL_TO_HOST_FLOW. Treat it as non-fatal so init can continue.
       */

      wlwarn("WARNING: SET_CTL_TO_HOST_FLOW unsupported (ret=%d), "
             "continuing without flow control\n", ret);
    }

  if (lmp_bredr_capable(g_btdev))
    {
      FAR struct bt_hci_cp_write_le_host_supp_s *cp;

      /* Use BR/EDR buffer size if LE reports zero buffers */

      if (!g_btdev.le_mtu)
        {
          ret = bt_hci_cmd_send_sync(BT_HCI_OP_READ_BUFFER_SIZE, NULL, &rsp);
          if (ret < 0)
            {
              wlerr("ERROR:  bt_hci_cmd_send_sync failed: %d\n", ret);
              return ret;
            }

          read_buffer_size_complete(rsp);
          bt_buf_release(rsp);
        }

      buf = bt_hci_cmd_create(BT_HCI_OP_LE_WRITE_LE_HOST_SUPP, sizeof(*cp));
      if (buf == NULL)
        {
          wlerr("ERROR:  Failed to create buffer\n");
          return -ENOBUFS;
        }

      /* Explicitly enable LE for dual-mode controllers */

      cp        = bt_buf_extend(buf, sizeof *cp);
      cp->le    = 0x01;
      cp->simul = 0x00;

      bt_hci_cmd_send_sync(BT_HCI_OP_LE_WRITE_LE_HOST_SUPP, buf, NULL);
    }

  wlinfo("HCI ver %u rev %u, manufacturer %u\n", g_btdev.hci_version,
         g_btdev.hci_revision, g_btdev.manufacturer);
  wlinfo("ACL buffers: pkts %u mtu %u\n", g_btdev.le_pkts, g_btdev.le_mtu);

  /* Initialize & prime the semaphore for counting controller-side available
   * ACL packet buffers.
   */

  nxsem_init(&g_btdev.le_pkts_sem, 0, g_btdev.le_pkts);
  return 0;
}

/****************************************************************************
 * Name: cmd_queue_deinit
 *
 * Description:
 *   Threads, fifos and semaphores deinitialization
 *
 * Input Parameters:
 *   none
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void cmd_queue_deinit(void)
{
  int ret;
  FAR struct bt_buf_s *buf;

  /* Tell the tx thread that the module is disconnected.
   */

  g_btdev.tx_status = ENOTCONN;

  /* Make sure the thread is not blocked by the semaphore.
   */

  nxsem_post(&g_btdev.ncmd_sem);

  /* We create and push a packet into the tx queue to unblock the thread.
   * Any packet will do.
   */

  buf = bt_hci_cmd_create(BT_HCI_OP_RESET, 0);
  if (buf)
    {
      ret = bt_queue_send(&g_btdev.tx_queue, buf, BT_NORMAL_PRIO);
      if (ret < 0)
        {
          wlerr("ERROR: bt_queue_send() failed: %d\n", ret);
        }
    }

  /* Wait for the tx thread to exit gracefully. */

  while (g_btdev.tx_status == ENOTCONN)
    {
      nxsig_usleep(1000);
    }

  /* Deinitialization */

  nxsem_destroy(&g_btdev.ncmd_sem);
  file_mq_close(&g_btdev.tx_queue);
  work_cancel(HPWORK, &g_hp_work);
  work_cancel(LPWORK, &g_lp_work);
}
#endif

/* threads, fifos and semaphores initialization */

static void cmd_queue_init(void)
{
  int ret;
#ifdef CONFIG_BLUETOOTH_TXCMD_PINNED_TO_CORE
  cpu_set_t cpuset;
#endif
  int pid;

  /* When there is a command to be sent to the Bluetooth driver, it queued on
   * the Tx queue and received by logic on the Tx kernel thread.
   */

  ret = bt_queue_open(BT_HCI_TX, O_RDWR | O_CREAT | O_CLOEXEC,
                      CONFIG_BLUETOOTH_TXCMD_NMSGS, &g_btdev.tx_queue);
  DEBUGASSERT(ret >= 0);

  nxsem_init(&g_btdev.ncmd_sem, 0, 1);

  g_btdev.ncmd = 1;
  g_btdev.tx_status = OK;

#ifdef CONFIG_BLUETOOTH_TXCMD_PINNED_TO_CORE
  sched_lock();
#endif

  pid = kthread_create("BT HCI Tx", CONFIG_BLUETOOTH_TXCMD_PRIORITY,
                       CONFIG_BLUETOOTH_TXCMD_STACKSIZE,
                       hci_tx_kthread, NULL);
  DEBUGASSERT(pid > 0);

#ifdef CONFIG_BLUETOOTH_TXCMD_PINNED_TO_CORE
  CPU_ZERO(&cpuset);
  CPU_SET((CONFIG_BLUETOOTH_TXCMD_CORE - 1), &cpuset);
  ret = nxsched_set_affinity(pid, sizeof(cpuset), &cpuset);
  if (ret)
    {
      wlerr("Failed to set affinity error=%d\n", ret);
      DEBUGPANIC();
    }

  sched_unlock();
#endif

  UNUSED(ret);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bt_send
 *
 * Description:
 *   Send the provided buffer to the bluetooth driver
 *
 * Input Parameters:
 *   btdev - An instance of the low-level drivers interface structure.
 *   buf   - The buffer to be sent by the driver
 *
 * Returned Value:
 *   Zero is returned on success; a negated errno value is returned on any
 *   failure.
 *
 ****************************************************************************/

int bt_send(FAR struct bt_driver_s *btdev,
            FAR struct bt_buf_s *buf)
{
  /* Send to driver */

  return btdev->send(btdev, buf->type, buf->data, buf->len);
}

/****************************************************************************
 * Name: bt_initialize
 *
 * Description:
 *   Initialize Bluetooth. Must be the called before anything else.
 *
 * Returned Value:
 *    Zero on success or (negative) error code otherwise.
 *
 ****************************************************************************/

int bt_initialize(void)
{
  FAR struct bt_driver_s *btdev = g_btdev.btdev;
  int ret;

  wlinfo("btdev %p\n", btdev);

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
  g_callback_list = NULL;
  g_scan_dev_found_cb = NULL;
#endif

  memset(&g_lp_rxlist, 0, sizeof(g_lp_rxlist));
  memset(&g_hp_rxlist, 0, sizeof(g_hp_rxlist));

  spin_lock_init(&g_hp_rxlist.lock);
  spin_lock_init(&g_lp_rxlist.lock);

  DEBUGASSERT(btdev != NULL);
  bt_buf_initialize();

  cmd_queue_init();

  ret = btdev->open(btdev);
  if (ret < 0)
    {
#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
      cmd_queue_deinit();
#endif
      wlerr("ERROR: HCI driver open failed (%d)\n", ret);
      return ret;
    }

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
  ret = hci_initialize();
  if (ret < 0)
    {
      cmd_queue_deinit();
      wlerr("ERROR:  hci_initialize failed: %d\n", ret);
      return ret;
    }

  ret = bt_l2cap_init();
#endif

  return ret;
}

/****************************************************************************
 * Name: bt_deinitialize
 *
 * Description:
 *   Deinitialize Bluetooth.
 *
 * Returned Value:
 *    Zero on success or (negative) error code otherwise.
 *
 ****************************************************************************/

int bt_deinitialize(void)
{
#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST
  FAR struct bt_driver_s *btdev = g_btdev.btdev;

  cmd_queue_deinit();

  /* Call the bluetooth HCI driver's close function if available. */

  if (btdev)
    {
      if (btdev->close)
        {
          btdev->close(btdev);
        }
    }
#endif

  return OK;
}

/****************************************************************************
 * Name: bt_driver_set
 *
 * Description:
 *   Set the Bluetooth low-level driver with the Bluetooth stack.
 *   This is called from the low-level driver and is part of the driver
 *   interface prototyped in include/nuttx/wireless/bluetooth/bt_driver.h
 *
 *   This function associates the Bluetooth driver with the Bluetooth stack.
 *
 * Input Parameters:
 *   btdev - An instance of the low-level drivers interface structure.
 *
 * Returned Value:
 *  Zero is returned on success; a negated errno value is returned on any
 *  failure.
 *
 ****************************************************************************/

int bt_driver_set(FAR struct bt_driver_s *btdev)
{
  DEBUGASSERT(btdev != NULL && btdev->open != NULL && btdev->send != NULL);

  if (g_btdev.btdev != NULL)
    {
      wlwarn("WARNING:  Already registered\n");
      return -EALREADY;
    }

  memset(&g_btdev, 0, sizeof(g_btdev));

  g_btdev.btdev = btdev;
  return 0;
}

/****************************************************************************
 * Name: bt_driver_unset
 *
 * Description:
 *   Unset a Bluetooth low-level driver previously set with bt_driver_set.
 *   This may be called from the low-level driver and is part of the driver
 *   interface prototyped in include/nuttx/wireless/bluetooth/bt_driver.h
 *
 * Input Parameters:
 *   btdev - An instance of the low-level drivers interface structure.
 *
 * Returned Value:
 *  None
 *
 ****************************************************************************/

void bt_driver_unset(FAR struct bt_driver_s *btdev)
{
  g_btdev.btdev = NULL;
}

/****************************************************************************
 * Name: bt_receive
 *
 * Description:
 *   Called by the Bluetooth low-level driver when new data is received from
 *   the radio.  This may be called from the low-level driver and is part of
 *   the driver interface prototyped in
 *   include/nuttx/wireless/bluetooth/bt_driver.h
 *
 *   NOTE:  This function will defer all real work to the low or to the high
 *   priority work queues.  Therefore, this function may safely be called
 *   from interrupt handling logic.
 *
 * Input Parameters:
 *   buf - An instance of the buffer structure providing the received frame.
 *
 * Returned Value:
 *  None
 *
 ****************************************************************************/

int bt_receive(FAR struct bt_driver_s *btdev, enum bt_buf_type_e type,
               FAR void *data, size_t len)
{
  FAR struct bt_hci_evt_hdr_s *hdr;
  struct bt_buf_s *buf;
  int ret;

  wlinfo("data %p len %zu\n", data, len);

  /* Critical command complete/status events use the high priority work
   * queue.
   */

  buf = bt_buf_alloc(type, NULL, BLUETOOTH_H4_HDRLEN);
  if (buf == NULL)
    {
      return -ENOMEM;
    }

  memcpy(bt_buf_extend(buf, len), data, len);

  if (type != BT_ACL_IN)
    {
      if (type != BT_EVT)
        {
          wlerr("ERROR: Invalid buf type %u\n", buf->type);
          bt_buf_release(buf);
          return -EINVAL;
        }

      /* Command Complete/Status events use high priority messages. */

      hdr = (FAR void *)buf->data;
      if (hdr->evt == BT_HCI_EVT_CMD_COMPLETE ||
          hdr->evt == BT_HCI_EVT_CMD_STATUS ||
          hdr->evt == BT_HCI_EVT_NUM_COMPLETED_PACKETS)
        {
          /* Add the buffer to the high priority Rx buffer list */

          bt_enqueue_bufwork(&g_hp_rxlist, buf);

          /* If there is already pending work, then do nothing.  Otherwise,
           * schedule processing of the Rx buffer list on the high priority
           * work queue.
           */

          if (work_available(&g_hp_work))
            {
              ret = work_queue(HPWORK, &g_hp_work, priority_rx_work,
                               &g_hp_rxlist, 0);
              if (ret < 0)
                {
                  wlerr("ERROR:  Failed to schedule HPWORK: %d\n", ret);
                }
            }

          return OK;
        }
    }

  /* All others use the low priority work queue */

  /* Add the buffer to the low priority Rx buffer list */

  bt_enqueue_bufwork(&g_lp_rxlist, buf);

  /* If there is already pending work, then do nothing.  Otherwise, schedule
   * processing of the Rx buffer list on the low priority work queue.
   */

  if (work_available(&g_lp_work))
    {
      ret = work_queue(LPWORK, &g_lp_work, hci_rx_work, &g_lp_rxlist, 0);
      if (ret < 0)
        {
          wlerr("ERROR:  Failed to schedule LPWORK: %d\n", ret);
        }
    }

  return OK;
}

#ifdef CONFIG_WIRELESS_BLUETOOTH_HOST

/****************************************************************************
 * Name: bt_hci_cmd_create
 *
 * Description:
 *   Allocate and initialize a buffer for a command
 *
 * Returned Value:
 *   A reference to the allocated buffer.  NULL could possibly be returned
 *   on any failure to allocate.
 *
 ****************************************************************************/

FAR struct bt_buf_s *bt_hci_cmd_create(uint16_t opcode, uint8_t param_len)
{
  FAR struct bt_hci_cmd_hdr_s *hdr;
  FAR struct bt_buf_s *buf;

  wlinfo("opcode %04x param_len %u\n", opcode, param_len);

  buf = bt_buf_alloc(BT_CMD, NULL, g_btdev.btdev->head_reserve);
  if (!buf)
    {
      wlerr("ERROR: Cannot get free buffer\n");
      return NULL;
    }

  wlinfo("buf %p\n", buf);

  buf->u.hci.opcode = opcode;
  buf->u.hci.sync   = NULL;

  hdr              = bt_buf_extend(buf, sizeof(*hdr));
  hdr->opcode      = BT_HOST2LE16(opcode);
  hdr->param_len   = param_len;

  return buf;
}

int bt_hci_cmd_send(uint16_t opcode, FAR struct bt_buf_s *buf)
{
  int ret;

  if (buf == NULL)
    {
      buf = bt_hci_cmd_create(opcode, 0);
      if (buf == NULL)
        {
          wlerr("ERROR:  Failed to create buffer\n");
          return -ENOBUFS;
        }
    }

  wlinfo("opcode %04x len %u\n", opcode, buf->len);

  /* Host Number of Completed Packets can ignore the ncmd value and does not
   * generate any cmd complete/status events.
   */

  if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS)
    {
      bt_send(g_btdev.btdev, buf);
      bt_buf_release(buf);
      return 0;
    }

  ret = bt_queue_send(&g_btdev.tx_queue, buf, BT_NORMAL_PRIO);
  if (ret < 0)
    {
      wlerr("ERROR: bt_queue_send() failed: %d\n", ret);
    }

  return ret;
}

int bt_hci_cmd_send_sync(uint16_t opcode, FAR struct bt_buf_s *buf,
                         FAR struct bt_buf_s **rsp)
{
  sem_t sync_sem;
  int ret;

  /* NOTE: This function cannot be called from the rx thread since it relies
   * on the very same thread in processing the cmd_complete event and giving
   * back the blocking semaphore.
   */

  if (buf == NULL)
    {
      buf = bt_hci_cmd_create(opcode, 0);
      if (buf == NULL)
        {
          wlerr("ERROR:  Failed to create buffer\n");
          return -ENOBUFS;
        }
    }

  wlinfo("opcode %04x len %u\n", opcode, buf->len);

  /* Set up for the wait */

  nxsem_init(&sync_sem, 0, 0);
  buf->u.hci.sync = &sync_sem;

  /* Send the frame */

  ret = bt_queue_send(&g_btdev.tx_queue, buf, BT_NORMAL_PRIO);
  if (ret < 0)
    {
      wlerr("ERROR: bt_queue_send() failed: %d\n", ret);
    }
  else
    {
      /* Wait for the response to the command.  An I/O error will be
       * declared if the response does not occur within the timeout
       * interval.
       *
       * REVISIT: The cause of the timeout could be a failure to receive a
       * response to a sent frame or, perhaps, a failure to send the frame.
       * Should there also be logic to flush any unsent Tx packets?
       */

      ret = nxsem_tickwait_uninterruptible(&sync_sem,
                                           MSEC2TICK(TIMEOUT_MSEC));
    }

  /* Indicate failure if we failed to get the response */

  if (ret >= 0)
    {
      if (buf->u.hci.sync == NULL)
        {
          wlerr("ERROR:  Failed get return parameters\n");
          ret = -EIO;
        }
      else
        {
          ret = 0;
        }
    }

  /* Note: if ret < 0 the packet might just be delayed and could still
   * be sent.  We cannot decrease the ref count since it if it was sent
   * it buf could be pointed a completely different request.
   */

  if (rsp != NULL)
    {
      /* If the response is expected provide the sync response */

      *rsp = buf->u.hci.sync;
    }
  else if (buf->u.hci.sync != NULL)
    {
      /* If a sync response was given but not requested drop it */

      bt_buf_release(buf->u.hci.sync);
    }

  nxsem_destroy(&sync_sem);

  return ret;
}

/****************************************************************************
 * Name: bt_start_advertising
 *
 * Description:
 *   Set advertisement data, scan response data, advertisement parameters
 *   and start advertising.
 *
 * Input Parameters:
 *   type - Advertising type.
 *   ad   - Data to be used in advertisement packets.
 *   sd   - Data to be used in scan response packets.
 *
 * Returned Value:
 *   Zero on success or (negative) error code otherwise.
 *
 ****************************************************************************/

int bt_start_advertising(uint8_t type, FAR const struct bt_eir_s *ad,
                         FAR const struct bt_eir_s *sd)
{
  FAR struct bt_buf_s *buf;
  FAR struct bt_hci_cp_le_set_adv_data_s *set_data;
  FAR struct bt_hci_cp_le_set_adv_data_s *scan_rsp;
  FAR struct bt_hci_cp_le_set_adv_parameters_s *set_param;
  int i;

  if (ad == NULL)
    {
      goto send_scan_rsp;
    }

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_DATA, sizeof(*set_data));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  set_data = bt_buf_extend(buf, sizeof(*set_data));

  memset(set_data, 0, sizeof(*set_data));

  for (i = 0; ad[i].len > 0; i++)
    {
      /* Check if ad fit in the remaining buffer */

      if (set_data->len + ad[i].len + 1 > 29)
        {
          break;
        }

      memcpy(&set_data->data[set_data->len], &ad[i], ad[i].len + 1);
      set_data->len += ad[i].len + 1;
    }

  bt_hci_cmd_send(BT_HCI_OP_LE_SET_ADV_DATA, buf);

send_scan_rsp:
  if (sd == NULL)
    {
      goto send_set_param;
    }

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_SCAN_RSP_DATA,
                          sizeof(*scan_rsp));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  scan_rsp = bt_buf_extend(buf, sizeof(*scan_rsp));

  memset(scan_rsp, 0, sizeof(*scan_rsp));

  for (i = 0; sd[i].len > 0; i++)
    {
      /* Check if ad fit in the remaining buffer */

      if (scan_rsp->len + sd[i].len + 1 > 29)
        {
          break;
        }

      memcpy(&scan_rsp->data[scan_rsp->len], &sd[i], sd[i].len + 1);
      scan_rsp->len += sd[i].len + 1;
    }

  bt_hci_cmd_send(BT_HCI_OP_LE_SET_SCAN_RSP_DATA, buf);

send_set_param:
  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_PARAMETERS,
                          sizeof(*set_param));
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  set_param = bt_buf_extend(buf, sizeof(*set_param));

  memset(set_param, 0, sizeof(*set_param));
  set_param->min_interval = BT_HOST2LE16(300);
  set_param->max_interval = BT_HOST2LE16(300);
  set_param->type         = type;
  set_param->channel_map  = 0x07;

  bt_hci_cmd_send(BT_HCI_OP_LE_SET_ADV_PARAMETERS, buf);

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_ENABLE, 1);
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  g_btdev.adv_enable = 0x01;
  memcpy(bt_buf_extend(buf, 1), &g_btdev.adv_enable, 1);

  return bt_hci_cmd_send_sync(BT_HCI_OP_LE_SET_ADV_ENABLE, buf, NULL);
}

/****************************************************************************
 * Name: bt_stop_advertising
 *
 * Description:
 *   Stops ongoing advertising.
 *
 * Returned Value:
 *   Zero on success or (negative) error code otherwise.
 *
 ****************************************************************************/

int bt_stop_advertising(void)
{
  FAR struct bt_buf_s *buf;
  if (!g_btdev.adv_enable)
    {
      wlwarn("WARNING:  Already advertising\n");
      return -EALREADY;
    }

  buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_ENABLE, 1);
  if (buf == NULL)
    {
      wlerr("ERROR:  Failed to create buffer\n");
      return -ENOBUFS;
    }

  g_btdev.adv_enable = 0x00;
  memcpy(bt_buf_extend(buf, 1), &g_btdev.adv_enable, 1);

  return bt_hci_cmd_send_sync(BT_HCI_OP_LE_SET_ADV_ENABLE, buf, NULL);
}

/****************************************************************************
 * Name: bt_start_scanning
 *
 * Description:
 *   Start LE scanning with and provide results through the specified
 *   callback.
 *
 * Input Parameters:
 *   filter_dups - Enable duplicate filtering (or not).
 *   cb          - Callback to notify scan results.
 *
 * Returned Value:
 *   Zero on success or error code otherwise, positive in case
 *   of protocol error or negative (POSIX) in case of stack internal error
 *
 ****************************************************************************/

int bt_start_scanning(uint8_t scan_filter, bt_le_scan_cb_t cb)
{
  /* Return if active scan is already enabled */

  if (g_scan_dev_found_cb)
    {
      wlwarn("WARNING:  Already scanning\n");
      return -EALREADY;
    }

  g_scan_dev_found_cb = cb;
  g_btdev.scan_filter = scan_filter;

  return bt_le_scan_update();
}

/****************************************************************************
 * Name: bt_stop_scanning
 *
 * Description:
 *   Stops ongoing LE scanning.
 *
 * Returned Value:
 *   Zero on success or error code otherwise, positive in case
 *   of protocol error or negative (POSIX) in case of stack internal error
 *
 ****************************************************************************/

int bt_stop_scanning(void)
{
  /* Return if active scanning is already disabled */

  if (g_scan_dev_found_cb == NULL)
    {
      wlwarn("WARNING:  Not scanning\n");
      return -EALREADY;
    }

  g_scan_dev_found_cb = NULL;
  g_btdev.scan_filter = BT_LE_SCAN_FILTER_DUP_ENABLE;

  return bt_le_scan_update();
}

/****************************************************************************
 * Name: bt_le_scan_update
 *
 * Description:
 *   Used to determine whether to start scan and which scan type should be
 *   used.
 *
 * Returned Value:
 *   Zero on success or error code otherwise, positive in case
 *   of protocol error or negative (POSIX) in case of stack internal error
 *
 ****************************************************************************/

int bt_le_scan_update(void)
{
  FAR struct bt_conn_s *conn;
  int ret;

  if (g_btdev.scan_enable)
    {
      if (g_scan_dev_found_cb)
        {
          return 0;
        }

      ret = bt_hci_stop_scanning();
      if (ret)
        {
          return ret;
        }
    }

  if (g_scan_dev_found_cb)
    {
      return bt_hci_start_scanning(BT_LE_SCAN_ACTIVE, g_btdev.scan_filter);
    }

  conn = bt_conn_lookup_state(BT_ADDR_LE_ANY, BT_CONN_CONNECT_SCAN);
  if (!conn)
    {
      return 0;
    }

  bt_conn_release(conn);
  return bt_hci_start_scanning(BT_LE_SCAN_PASSIVE, g_btdev.scan_filter);
}

/****************************************************************************
 * Name: bt_conn_cb_register
 *
 * Description:
 *   Register callbacks to monitor the state of connections.
 *
 * Input Parameters:
 *   cb - Instance of the callback structure.
 *
 ****************************************************************************/

void bt_conn_cb_register(FAR struct bt_conn_cb_s *cb)
{
  cb->flink       = g_callback_list;
  g_callback_list = cb;
}

FAR const char *bt_addr_str(FAR const bt_addr_t *addr)
{
  static char bufs[2][18];
  static uint8_t cur;
  FAR char *str;

  str  = bufs[cur++];
  cur %= nitems(bufs);
  bt_addr_to_str(addr, str, sizeof(bufs[cur]));

  return str;
}

FAR const char *bt_addr_le_str(FAR const bt_addr_le_t *addr)
{
  static char bufs[2][27];
  static uint8_t cur;
  FAR char *str;

  str  = bufs[cur++];
  cur %= nitems(bufs);
  bt_addr_le_to_str(addr, str, sizeof(bufs[cur]));

  return str;
}

#else

/****************************************************************************
 * Name: bt_hci_cb_register
 *
 * Description:
 *   Register callbacks to handle RAW HCI packets
 *
 * Input Parameters:
 *   cb - Instance of the callback structure.
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

void bt_hci_cb_register(FAR struct bt_hci_cb_s *cb)
{
  g_hci_cb = cb;
}

#endif

"}

{"content":"/****************************************************************************
 * app/agent_camera/agent_camera_main.c
 *
 * Bench for the camera side of the ai_agent port.
 *
 * packages/ai_agent's camera_capture tool (src/tools/tool_camera.c) reaches
 * the camera through V4L2 and then hands the frame straight to a Vision LLM.
 * On this board the LLM half cannot run yet -- the AP core has no network
 * device (Wi-Fi lives on CP) -- so the tool as a whole cannot be exercised
 * on hardware.  Everything up to the LLM call can be, and that half is what
 * the board actually has to provide.
 *
 * This command runs exactly that half: the same ioctl order, the same
 * V4L2_MEMORY_MMAP buffers, the same JPEG-then-ENTROPY format fallback, the
 * same poll() timeout, the same "one frame, then stop" shape.  What it does
 * differently is only what happens afterwards: instead of posting the frame
 * to an LLM it checks the JPEG markers, prints the byte count and can write
 * the frame to a file.
 *
 * Two things it is meant to answer, in this order:
 *
 *   1. Does the JPEG capture path work at all through V4L2?  The path is
 *      new (bk7258_jpeg_enc.c plus the JPEG branch of
 *      bk7258_camera_imgdata.c) and the UYVY path is the only one with
 *      board evidence behind it, so "JPEG works" cannot be assumed from
 *      "preview works".
 *
 *   2. Does tool_camera.c's *request* fit this board?  It asks for
 *      320x180 (its "low", the default) or 1280x720 ("high").  This driver
 *      programs 480x480 / 640x480 / 864x480 and rejects anything else --
 *      bk7258_gc2145_find_mode() is an exact match, not a nearest one --
 *      so the tool's own geometry is expected to fail VIDIOC_S_FMT here.
 *      `agent_camera low` reproduces that failure deliberately; `auto`
 *      picks a size the driver enumerates and shows the path works once
 *      the geometry is right.  The fix belongs upstream in tool_camera.c
 *      (negotiate via VIDIOC_ENUM_FRAMESIZES instead of hardcoding), and
 *      the negotiation implemented here is the prototype for it.
 *
 * Usage:
 *   agent_camera [auto|low|high|<W>x<H>] [options]
 *
 *     auto      (default) first JPEG size the driver enumerates
 *     low       320x180  -- tool_camera.c's default request
 *     high      1280x720 -- tool_camera.c's "high" request
 *     <W>x<H>   an explicit geometry
 *
 *   Options:
 *     out=<path>   write the frame (e.g. out=/mnt/cap.jpg; needs a mounted
 *                  filesystem -- see docs/reference/camera.md 9.3)
 *     b64          print the first frame as base64 between fence lines, to
 *                  retrieve it with no filesystem involved:
 *
 *                    ./serial_cmd.sh -r -w 60 -o /tmp/b64.log 'agent_camera b64'
 *                    sed -n '/BEGIN AGENT_CAMERA/,/END AGENT_CAMERA/p' /tmp/b64.log \
 *                      | sed '1d;$d' | tr -d '\r\n' | base64 -d > cap.jpg
 *
 *                  Then check it with a real decoder, not just the markers:
 *                  `identify cap.jpg` / PIL.  See docs/reference/camera.md
 *                  14.5-14.6 for why the marker check is not enough.
 *     n=<count>    capture <count> frames in one streaming session
 *                  (default 1, which is what the tool does)
 *     b64all       like b64 but for *every* frame of the session, each in
 *                  its own fenced block tagged with its index and length.
 *                  This is the recording interface: a burst comes out as a
 *                  sequence of JPEGs that the host assembles into a clip.
 *
 *                    ./serial_cmd.sh -r -w 150 -o /tmp/clip.log \
 *                       'agent_camera n=24 b64all'
 *
 *                  Every session also ends with a measured frame rate line
 *                  ("session N frame(s) in X ms = Y.YY fps").  Take that
 *                  number from a run *without* b64all: printing tens of
 *                  kilobytes per frame down a 115200 console dominates the
 *                  session and the rate reported with b64all is the console
 *                  speed, not the camera's.
 *     rec=<count>  record <count> frames into memory at the sensor's own
 *                  rate and dump them afterwards.  This is what a clip
 *                  needs: with b64all the console pace (3.5s per frame at
 *                  115200) sets the sampling interval and the result is a
 *                  time lapse, not motion.  Combine with n= large enough to
 *                  cover the recording, e.g.
 *
 *                    'agent_camera 640x480 bufs=4 n=60 rec=20'
 *
 *                  rec frames are kept out of the n captured, spread evenly:
 *                  n=60 rec=20 keeps every third frame, i.e. a 20-frame clip
 *                  at about 10fps with the sensor still running at 30.  Ask
 *                  for rec == n only at low resolution: copying a 640x480
 *                  frame out takes longer than the 33ms between frames (both
 *                  ends are non-cacheable PSRAM), the DMA catches up, and
 *                  most frames come back with a truncated scan.
 *
 *                  Frames are held in the heap, which reaches PSRAM here, so
 *                  30 x ~30KB is fine; the SRAM heap alone would not be.
 *     caps         only enumerate formats and sizes, capture nothing
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/types.h>

#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <limits.h>
#include <netinet/in.h>
#include <poll.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <nuttx/video/video.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CAM_DEV            "/dev/video0"

/* Mirrors tool_camera.c: two MMAP buffers, a 160KB sizeimage hint and a 5s
 * frame timeout.  The sizeimage hint is what v4l2_cap.c's get_bufsize()
 * uses for a compressed format, so it -- not width*height -- decides how
 * much the imgdata allocator takes out of PSRAM for each buffer.
 */

#define CAM_BUF_SIZE       (160 * 1024)
#define CAM_NUM_BUFFERS    2

/* How many buffers this tool can hold at once.  The *default* stays at
 * CAM_NUM_BUFFERS because that is what packages/ai_agent's camera_capture
 * asks for and this tool exists to reproduce it; 'bufs=4' is for recording,
 * where the copy out of each frame has to overlap the DMA filling the next
 * one and two buffers leave no slack.
 */

#define CAM_MAX_BUFFERS    4
#define CAM_TIMEOUT_MS     5000

/* tool_camera.c's two hardcoded geometries. */

#define TOOL_LOW_WIDTH     320
#define TOOL_LOW_HEIGHT    180
#define TOOL_HIGH_WIDTH    1280
#define TOOL_HIGH_HEIGHT   720

/* tool_camera.c's fallback format, spelled the same way it spells it. */

#ifndef V4L2_PIX_FMT_ENTROPY
#  define V4L2_PIX_FMT_ENTROPY  v4l2_fourcc('G', 'R', 'E', 'P')
#endif

#define MAX_ENUM_SIZES     16

/* base64 characters per output line.  Must be a multiple of 4 so a line never
 * splits a quad, and <= 255 so one line is exactly one CP bridge log entry
 * (AP_BRIDGE_LOG_LINE_SIZE = 256 in the CP's driver.c) -- see
 * agent_camera_print_b64().
 */

#define B64_LINE_CHARS     252

/* Bytes per second the console route is paced at.  The CP's UART0 runs at
 * 115200 8N1 = 11520 B/s and the CP drops rather than blocks when its log
 * queue backs up, so this has to stay under the drain rate with margin for
 * the driver's own log lines.  Raise it only together with the CP's baud.
 */

#define B64_CONSOLE_BPS    9600

/* TCP delivery: bytes handed to send() at a time, and how long to wait for
 * the connect.
 */

#define TCP_SEND_CHUNK     1460
#define TCP_CONNECT_MS     5000

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct agent_camera_size_s
{
  uint16_t width;
  uint16_t height;
};

struct agent_camera_s
{
  int      fd;
  void    *bufs[CAM_MAX_BUFFERS];
  size_t   buflen[CAM_MAX_BUFFERS];
  uint32_t nbuffers;
  bool     streaming;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Buffer count, settable with bufs=N.
 *
 * Exists because frames alternate good/short by buffer index on this board:
 * with two buffers the ones landing in index 0 come back at about 13.6KB and
 * do not decode, while index 1 gives a full ~43KB frame.  Being able to ask
 * for a single buffer separates "the JPEG path is broken" from "re-arming the
 * DMA onto the next buffer loses the head of the frame".
 */

static uint32_t g_nbufs = CAM_NUM_BUFFERS;

static void agent_camera_usage(void)
{
  printf("Usage: agent_camera [auto|low|high|<W>x<H>] "
         "[out=<path>] [n=<count>] [strict] [caps]\n"
         "  auto     first JPEG size the driver enumerates (default)\n"
         "  low      320x180, tool_camera.c's default request\n"
         "  high     1280x720, tool_camera.c's \"high\" request\n"
         "  strict   do not negotiate a refused geometry (pre-patch\n"
         "           tool_camera.c behaviour)\n"
         "  b64      print the last frame as base64 (retrieve without a\n"
         "           filesystem; see the file header)\n"
         "  b64all   print every frame as base64, one fenced block each\n"
         "  tcp=<ip>:<port>  push the frame over TCP as raw JPEG, one\n"
         "           connection per frame (host: nc -l -p <port> >f.jpg, or\n"
         "           tools/tcpframes.py).  Needs wlan0 up; far faster than\n"
         "           the console -- see agent_camera_send_tcp()\n"
         "  session=<id>  tag frames with a session id, sequence and\n"
         "           monotonic timestamp (the metadata an upload needs)\n"
         "  rec=<n>  record n frames at the sensor rate into memory, then\n"
         "           dump them all as base64 -- use this for a clip\n"
         "  caps     enumerate formats and sizes only\n");
}

/* Prints a fourcc the way the rest of the tree does, so log lines can be
 * grepped against the driver's own format tables.
 */

static void agent_camera_print_fourcc(uint32_t fourcc)
{
  printf("%c%c%c%c",
         (char)(fourcc & 0xff),
         (char)((fourcc >> 8) & 0xff),
         (char)((fourcc >> 16) & 0xff),
         (char)((fourcc >> 24) & 0xff));
}

/****************************************************************************
 * Name: agent_camera_enum
 *
 * Description:
 *   Enumerates the formats the device offers and, for each, its discrete
 *   frame sizes.  Collects the sizes belonging to want_fmt into sizes[].
 *
 *   This is the part tool_camera.c is missing: it hardcodes a geometry and
 *   gives up when VIDIOC_S_FMT rejects it, with no way to learn what the
 *   device would have accepted.  Everything the driver can do is already
 *   discoverable through these two ioctls.
 *
 * Returned Value:
 *   Number of sizes collected for want_fmt, or a negated errno.
 *
 ****************************************************************************/

static int agent_camera_enum(int fd, uint32_t want_fmt,
                            struct agent_camera_size_s *sizes,
                            size_t max_sizes, bool verbose)
{
  struct v4l2_fmtdesc fmtdesc;
  unsigned int nsizes = 0;
  unsigned int i;

  for (i = 0; ; i++)
    {
      memset(&fmtdesc, 0, sizeof(fmtdesc));
      fmtdesc.index = i;
      fmtdesc.type  = V4L2_BUF_TYPE_VIDEO_CAPTURE;

      if (ioctl(fd, VIDIOC_ENUM_FMT, (uintptr_t)&fmtdesc) < 0)
        {
          break;
        }

      if (verbose)
        {
          printf("agent_camera: format[%u] ", i);
          agent_camera_print_fourcc(fmtdesc.pixelformat);
          printf(" flags=0x%" PRIx32 " %s\n",
                 (uint32_t)fmtdesc.flags,
                 fmtdesc.description[0] ? (char *)fmtdesc.description : "");
        }

      /* Sizes are enumerated per format, so this inner loop has to run for
       * every format even when only one of them is wanted: the framesize
       * enumeration is indexed by (pixel_format, index) and the driver
       * returns EINVAL for an index that belongs to another format.
       */

      unsigned int j;

      for (j = 0; ; j++)
        {
          struct v4l2_frmsizeenum frmsize;

          memset(&frmsize, 0, sizeof(frmsize));
          frmsize.index        = j;
          frmsize.pixel_format = fmtdesc.pixelformat;
          frmsize.buf_type     = V4L2_BUF_TYPE_VIDEO_CAPTURE;

          if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, (uintptr_t)&frmsize) < 0)
            {
              break;
            }

          if (frmsize.type != V4L2_FRMSIZE_TYPE_DISCRETE)
            {
              continue;
            }

          if (verbose)
            {
              printf("agent_camera:   size[%u] %" PRIu32 "x%" PRIu32 "\n",
                     j,
                     (uint32_t)frmsize.discrete.width,
                     (uint32_t)frmsize.discrete.height);
            }

          if (fmtdesc.pixelformat == want_fmt && nsizes < max_sizes)
            {
              sizes[nsizes].width  = (uint16_t)frmsize.discrete.width;
              sizes[nsizes].height = (uint16_t)frmsize.discrete.height;
              nsizes++;
            }
        }
    }

  if (i == 0)
    {
      printf("agent_camera: VIDIOC_ENUM_FMT rejected index 0: %d\n", errno);
      return -errno;
    }

  return (int)nsizes;
}

/****************************************************************************
 * Name: agent_camera_try_format
 *
 * Description:
 *   Offers one (geometry, pixel format) pair to the driver.  Sets sizeimage
 *   the way tool_camera.c does, since for a compressed format that is what
 *   decides how large a buffer the framework allocates.
 *
 ****************************************************************************/

static int agent_camera_try_format(int fd, int width, int height,
                                  uint32_t pixelformat)
{
  struct v4l2_format fmt;

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width       = width;
  fmt.fmt.pix.height      = height;
  fmt.fmt.pix.pixelformat = pixelformat;
  fmt.fmt.pix.sizeimage   = CAM_BUF_SIZE;
  fmt.fmt.pix.field       = V4L2_FIELD_NONE;

  return ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt) < 0 ? ERROR : OK;
}

/****************************************************************************
 * Name: agent_camera_set_format
 *
 * Description:
 *   tool_camera.c's format step: ask for V4L2_PIX_FMT_JPEG and, if that is
 *   refused, ask for V4L2_PIX_FMT_ENTROPY.
 *
 *   When negotiate is true this also mirrors the geometry negotiation in the
 *   overlay-managed complete target file:
 *   external/packages/ai_agent/src/tools/tool_camera.c
 *   A refused geometry is retried at the enumerated size whose pixel count
 *   is closest.  Same algorithm, same device, same driver, so `low` versus
 *   `low strict` directly compares the overlay behavior with the fixed
 *   baseline on this board.
 *
 *   Note that VIDIOC_ENUM_FRAMESIZES cannot be trusted to filter by pixel
 *   format: v4l2_cap.c's capture_enum_frmsize() indexes the imgsensor's
 *   frmsizes array and ignores f->pixel_format entirely, so every format
 *   enumerates every size.  VIDIOC_S_FMT is therefore the only authority on
 *   whether a (format, geometry) pair is real, which is why each candidate
 *   is put back through it rather than trusted because it was enumerated.
 *
 ****************************************************************************/

static int agent_camera_set_format(int fd, int *width, int *height,
                                  bool negotiate, uint32_t *out_fmt)
{
  static const uint32_t candidates[] =
  {
    V4L2_PIX_FMT_JPEG,
    V4L2_PIX_FMT_ENTROPY,
  };

  struct agent_camera_size_s sizes[MAX_ENUM_SIZES];
  size_t c;

  for (c = 0; c < sizeof(candidates) / sizeof(candidates[0]); c++)
    {
      if (agent_camera_try_format(fd, *width, *height, candidates[c]) == OK)
        {
          *out_fmt = candidates[c];
          return OK;
        }

      printf("agent_camera: S_FMT ");
      agent_camera_print_fourcc(candidates[c]);
      printf(" %dx%d failed: %d\n", *width, *height, errno);
    }

  if (!negotiate)
    {
      return -EINVAL;
    }

  for (c = 0; c < sizeof(candidates) / sizeof(candidates[0]); c++)
    {
      unsigned long want = (unsigned long)(*width) *
                           (unsigned long)(*height);
      unsigned long best_delta = ULONG_MAX;
      int best_w = 0;
      int best_h = 0;
      int nsizes;
      int i;

      nsizes = agent_camera_enum(fd, candidates[c], sizes,
                                 MAX_ENUM_SIZES, false);
      if (nsizes <= 0)
        {
          continue;
        }

      for (i = 0; i < nsizes; i++)
        {
          unsigned long area = (unsigned long)sizes[i].width *
                               (unsigned long)sizes[i].height;
          unsigned long delta = area > want ? area - want : want - area;

          if (delta < best_delta)
            {
              best_delta = delta;
              best_w = sizes[i].width;
              best_h = sizes[i].height;
            }
        }

      if (best_w == 0 || (best_w == *width && best_h == *height))
        {
          continue;
        }

      if (agent_camera_try_format(fd, best_w, best_h, candidates[c]) == OK)
        {
          printf("agent_camera: %dx%d refused, using enumerated %dx%d\n",
                 *width, *height, best_w, best_h);
          *width   = best_w;
          *height  = best_h;
          *out_fmt = candidates[c];
          return OK;
        }
    }

  return -EINVAL;
}

/****************************************************************************
 * Name: agent_camera_check_jpeg
 *
 * Description:
 *   Reports whether the frame is a structurally valid JPEG file.
 *
 *   This used to check only SOI at the front and EOI at the end, and that
 *   judgement was wrong in a way worth spelling out: a frame can pass it and
 *   still be undecodable.  The encoder on this board emits
 *   SOI / APP0 / SOF0 / DQT / DHT and then entropy data with **no SOS
 *   segment**, so libjpeg rejects the file outright ("Invalid JPEG file
 *   structure: missing SOS marker") while SOI and EOI are both present.  A
 *   check both the driver and this tool agreed on was simply not sufficient
 *   -- see docs/reference/camera.md 14.6.
 *
 *   So the segment chain is walked properly here.  Note that markers on this
 *   encoder are preceded by 0xFF fill bytes (three of them, e.g.
 *   ff ff ff ff db); the standard permits that, and a scanner that does not
 *   skip fill will desynchronise and report segments that do not exist.
 *
 ****************************************************************************/

static void agent_camera_check_jpeg(const uint8_t *data, size_t len)
{
  bool have_sof = false;
  bool have_sos = false;
  bool have_dqt = false;
  bool have_dht = false;
  size_t i = 0;

  if (len < 4)
    {
      printf("agent_camera: frame too short to inspect (%zu bytes)\n", len);
      return;
    }

  if (data[0] != 0xff || data[1] != 0xd8)
    {
      printf("agent_camera: no SOI: starts %02x %02x\n", data[0], data[1]);
      return;
    }

  /* Walk the segments.  Stops at SOS, which is where entropy data begins. */

  i = 2;
  while (i + 1 < len)
    {
      uint8_t marker;
      size_t seglen;

      if (data[i] != 0xff)
        {
          break;
        }

      /* Skip fill bytes: any number of 0xFF may precede a marker. */

      while (i + 1 < len && data[i + 1] == 0xff)
        {
          i++;
        }

      if (i + 1 >= len)
        {
          break;
        }

      marker = data[i + 1];

      if (marker == 0xd9)
        {
          break;
        }

      if (marker == 0xda)
        {
          have_sos = true;
          break;
        }

      if (i + 3 >= len)
        {
          break;
        }

      seglen = ((size_t)data[i + 2] << 8) | data[i + 3];
      if (seglen < 2)
        {
          break;
        }

      switch (marker)
        {
          case 0xc0:
          case 0xc1:
            have_sof = true;
            break;

          case 0xdb:
            have_dqt = true;
            break;

          case 0xc4:
            have_dht = true;
            break;

          default:
            break;
        }

      i += 2 + seglen;
    }

  printf("agent_camera: structure SOF=%s DQT=%s DHT=%s SOS=%s EOI=%s\n",
         have_sof ? "yes" : "NO", have_dqt ? "yes" : "NO",
         have_dht ? "yes" : "NO", have_sos ? "yes" : "NO",
         (data[len - 2] == 0xff && data[len - 1] == 0xd9) ? "yes" : "NO");

  if (!have_sos)
    {
      printf("agent_camera: NOT a decodable JPEG -- no SOS segment, so the "
             "entropy data has no scan header.  A Vision LLM (or any "
             "standard decoder) will reject this.  See "
             "docs/reference/camera.md 14.6\n");
    }
}

/****************************************************************************
 * Name: agent_camera_print_b64
 *
 * Description:
 *   Prints the frame as base64 between two fence lines, so it can be pulled
 *   off the board without a filesystem.
 *
 *   The alternative is `hexdump` plus docs/tools/hexdump2raw.py, which works
 *   (and is what first got a frame onto the host) but needs a mounted
 *   filesystem, costs 4.4 bytes of console per payload byte -- a 35KB frame
 *   became 170KB of serial output -- and has to be parsed with tolerance for
 *   block headers, ANSI escapes and the ASCII column.  base64 is 1.37 bytes
 *   per byte and `base64 -d` is exact, so there is nothing to get wrong on
 *   the host side.
 *
 *   Written in 252-character lines straight to fd 1 with write(), not through
 *   stdout's buffer, and with no intermediate copy of the frame: a second
 *   copy of a 160KB frame does not fit in the AP's kernel heap.
 *
 *   Both the line size and the pacing are transport facts, not taste.
 *   Measured 2026-08-17 on 640x480 (~36.4KB frames):
 *
 *     76-char lines via fwrite + usleep(30ms)/2 lines : 41.5s, 1.19KB/s
 *     1024-char lines via write(), no pacing          :  2.5s, but LOSSY
 *     252-char lines via write() + clock pacing       : see docs/, lossless
 *
 *   Two independent limits, found in that order:
 *
 *   1. Cost per write(), not per byte.  CONFIG_STDIO_LINEBUFFER with
 *      CONFIG_STDIO_BUFFER_SIZE=64 turns every 76-char line into two flushes;
 *      each flush becomes its own mailbox transaction, and
 *      bk7258_mb_uart.c's worker advances on a 10ms tick
 *      (MB_UART_WORK_INTERVAL) carrying at most 128 bytes
 *      (BK7258_MB_UART_CHUNK_SIZE).  38 bytes per 10ms tick is ~4KB/s at any
 *      baud rate.  One write() per line fixes that.
 *
 *   2. The CP drops instead of blocking.  With the pacing removed the run
 *      finished in 2.5s but the payload was short, and the CP's own counter
 *      says why: `ap_console status` went from qfail=158 to qfail=317 across
 *      one frame, i.e. 159 discarded entries, while rx_bytes rose by the full
 *      56659.  So the AP handed everything over and the CP threw part of it
 *      away -- its bridge calls shell_log_raw_data_nonblock() and only bumps
 *      a counter on failure (CP driver.c, ap_bridge_log_output()).  The
 *      mailbox-level RTS the AP honours covers the CP's mailbox rx_buf, not
 *      the shell log queue behind it, so there is no end-to-end backpressure
 *      to lean on and the AP has to stay under the CP's drain rate itself.
 *
 *   Hence B64_CONSOLE_BPS and agent_camera_pace(): a clock-driven budget
 *   rather than a fixed sleep every N lines.  The old code did have such a
 *   sleep, but its comment described a "1024-byte bridge flushing half-lines
 *   on a 50ms timer" -- which is not what any of this code does (8192-byte
 *   ring, 128-byte chunks, 10ms worker) -- so the value could not be reasoned
 *   about, only re-tuned by trial.
 *
 *   The single write() also removes an interleaving hazard rather than adding
 *   one: uart_write() holds dev->xmit.lock for the whole call
 *   (nuttx/drivers/serial/serial.c), so a driver log line from another thread
 *   can land between payload lines but no longer inside one.  A log line
 *   spliced into the middle of a payload line is what b64frames.py has to
 *   discard, and discarding it loses the frame.
 *
 *   None of this makes the console fast.  11520 B/s is the ceiling and base64
 *   inflates by 4/3, so ~4.3s per frame is the floor here and 5 fps is out of
 *   reach by an order of magnitude.  Use tcp= when the network is up; this
 *   path exists for when it is not.
 *
 ****************************************************************************/

/****************************************************************************
 * Name: agent_camera_fnv1a
 *
 * Description:
 *   32-bit FNV-1a over the frame, printed next to the base64 fence so the
 *   host can prove the retrieval was lossless before drawing any conclusion
 *   about the picture.
 *
 *   This exists because two frames came back decoding only 8 rows while a
 *   third decoded fully, and "the board produced junk" and "the console
 *   dropped bytes" predict exactly the same thing on the host.  Length
 *   agreement does not separate them: a dropped chunk replaced by an
 *   interleaved driver log line keeps the byte count plausible.  FNV-1a is
 *   enough here (we are detecting loss, not defending against tampering)
 *   and costs one pass with no buffer.
 *
 ****************************************************************************/

static uint32_t agent_camera_fnv1a(const uint8_t *data, size_t len)
{
  uint32_t hash = 2166136261u;
  size_t i;

  for (i = 0; i < len; i++)
    {
      hash ^= (uint32_t)data[i];
      hash *= 16777619u;
    }

  return hash;
}

/****************************************************************************
 * Name: agent_camera_copy32
 *
 * Description:
 *   Word-at-a-time copy out of a capture buffer.  This libc's memcpy is
 *   byte-wise, and the source is non-cacheable PSRAM, so copying a ~28KB
 *   frame with it takes longer than the 33ms the sensor gives us between
 *   frames.  With only a couple of V4L2 buffers in flight that loses the
 *   race: the DMA reaches the buffer we are still reading and the frame
 *   comes out with a truncated scan -- SOI, EOI and every marker present, so
 *   the structure check passes, but a real decoder reports "broken data
 *   stream".  Measured before this existed: 3 of 29 recorded frames decoded.
 *
 *   Both ends are 4-byte aligned here (the capture buffers come from a PSRAM
 *   pool, the destination from malloc), and the tail is handled bytewise.
 *
 ****************************************************************************/

static void agent_camera_copy32(FAR uint8_t *dst, FAR const uint8_t *src,
                                size_t len)
{
  FAR uint32_t *d = (FAR uint32_t *)dst;
  FAR const uint32_t *s = (FAR const uint32_t *)src;
  size_t words = len >> 2;
  size_t i;

  for (i = 0; i < words; i++)
    {
      d[i] = s[i];
    }

  for (i = words << 2; i < len; i++)
    {
      dst[i] = src[i];
    }
}

static void agent_camera_write_all(FAR const char *buf, size_t len)
{
  while (len > 0)
    {
      ssize_t nwritten = write(STDOUT_FILENO, buf, len);

      if (nwritten <= 0)
        {
          if (nwritten < 0 && (errno == EINTR || errno == EAGAIN))
            {
              continue;
            }

          return;
        }

      buf += nwritten;
      len -= (size_t)nwritten;
    }
}

/****************************************************************************
 * Name: agent_camera_pace
 *
 * Description:
 *   Hold the cumulative output rate at B64_CONSOLE_BPS by sleeping only when
 *   we are ahead of that budget.  Paced against CLOCK_MONOTONIC and the total
 *   byte count, not with a fixed sleep every N lines: a fixed sleep has to be
 *   tuned for the worst case and then pays it always, and it silently becomes
 *   wrong the moment the line length or the baud rate changes.
 *
 ****************************************************************************/

static void agent_camera_pace(FAR const struct timespec *start,
                              unsigned long emitted)
{
  struct timespec now;
  unsigned long elapsed_ms;
  unsigned long budget_ms;

  clock_gettime(CLOCK_MONOTONIC, &now);

  elapsed_ms = (unsigned long)((now.tv_sec - start->tv_sec) * 1000 +
                               (now.tv_nsec - start->tv_nsec) / 1000000);
  budget_ms = emitted * 1000ul / B64_CONSOLE_BPS;

  if (budget_ms > elapsed_ms)
    {
      usleep((budget_ms - elapsed_ms) * 1000);
    }
}

static void agent_camera_print_b64(const uint8_t *data, size_t len)
{
  static const char tbl[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  static char line[B64_LINE_CHARS + 1];
  struct timespec t_start;
  unsigned long emitted = 0;
  size_t used = 0;
  size_t i;

  printf("agent_camera: payload len=%zu fnv1a=0x%08" PRIx32 "\n",
         len, agent_camera_fnv1a(data, len));

  printf("-----BEGIN AGENT_CAMERA JPEG %zu-----\n", len);

  /* Drain the fence line out of the stdio buffer before switching to raw
   * write(): everything below bypasses stdout's buffer, so anything still
   * sitting in it would surface after the payload.
   */

  fflush(stdout);
  clock_gettime(CLOCK_MONOTONIC, &t_start);

  for (i = 0; i < len; i += 3)
    {
      size_t remain = len - i;
      uint32_t v = (uint32_t)data[i] << 16;

      if (remain > 1)
        {
          v |= (uint32_t)data[i + 1] << 8;
        }

      if (remain > 2)
        {
          v |= data[i + 2];
        }

      line[used++] = tbl[(v >> 18) & 0x3f];
      line[used++] = tbl[(v >> 12) & 0x3f];
      line[used++] = remain > 1 ? tbl[(v >> 6) & 0x3f] : '=';
      line[used++] = remain > 2 ? tbl[v & 0x3f] : '=';

      if (used == B64_LINE_CHARS)
        {
          line[used++] = '\n';
          agent_camera_write_all(line, used);
          emitted += used;
          used = 0;
          agent_camera_pace(&t_start, emitted);
        }
    }

  if (used > 0)
    {
      line[used++] = '\n';
      agent_camera_write_all(line, used);
    }

  printf("-----END AGENT_CAMERA JPEG-----\n");
  fflush(stdout);
}

/****************************************************************************
 * Name: agent_camera_connect_timeout
 *
 * Description:
 *   connect() with an upper bound.  Returns true on success; on failure errno
 *   holds the reason (ETIMEDOUT when the bound expired) and the socket is
 *   left for the caller to close.
 *
 ****************************************************************************/

static bool agent_camera_connect_timeout(int sock,
                                         FAR const struct sockaddr_in *addr,
                                         int timeout_ms)
{
  struct pollfd pfd;
  int flags;
  int error = 0;
  socklen_t errlen = sizeof(error);
  int ret;

  flags = fcntl(sock, F_GETFL, 0);
  if (flags < 0 || fcntl(sock, F_SETFL, flags | O_NONBLOCK) < 0)
    {
      return false;
    }

  ret = connect(sock, (FAR const struct sockaddr *)addr, sizeof(*addr));
  if (ret < 0 && errno != EINPROGRESS)
    {
      return false;
    }

  if (ret < 0)
    {
      pfd.fd = sock;
      pfd.events = POLLOUT;
      pfd.revents = 0;

      ret = poll(&pfd, 1, timeout_ms);
      if (ret == 0)
        {
          errno = ETIMEDOUT;
          return false;
        }

      if (ret < 0)
        {
          return false;
        }

      if (getsockopt(sock, SOL_SOCKET, SO_ERROR, &error, &errlen) < 0)
        {
          return false;
        }

      if (error != 0)
        {
          errno = error;
          return false;
        }
    }

  /* Back to blocking so the send() loop below does not have to spin. */

  if (fcntl(sock, F_SETFL, flags) < 0)
    {
      return false;
    }

  return true;
}

/****************************************************************************
 * Name: agent_camera_send_tcp
 *
 * Description:
 *   Push one frame to <host>:<port> over TCP and close.  The close is the
 *   frame delimiter, so the host side can be `nc -l -p 5000 > frame.jpg`
 *   with nothing else involved; tools/tcpframes.py does the same thing for a
 *   burst, one file per connection.
 *
 *   Why this exists next to 'b64': the console cannot carry a frame at any
 *   useful rate.  115200 8N1 is 11.5KB/s and base64 inflates 36KB to 49KB,
 *   so 4.3s is the floor there even with a perfect transport -- and 5 fps of
 *   640x480 needs 125KB/s, which the console cannot reach at any baud this
 *   board offers.  The Wi-Fi path does not have that problem: the AP hands
 *   whole packets to the CP by reference over the mailbox
 *   (bk7258_wifi.c: wifi_send_node_async(), a node descriptor rather than a
 *   128-byte copy), so a frame is a few dozen packets, not a few hundred
 *   mailbox chunks.
 *
 *   The payload is the raw JPEG.  No base64 (saves 33%), no fence lines, no
 *   escaping: TCP already delivers bytes in order or not at all.  The
 *   len/fnv1a line is still printed on the console so the host can prove the
 *   file it received is the frame the board sent.
 *
 ****************************************************************************/

static int agent_camera_send_tcp(FAR const char *target,
                                 const uint8_t *data, size_t len)
{
  struct sockaddr_in addr;
  struct timespec t_start;
  struct timespec t_end;
  unsigned long elapsed_ms;
  FAR const char *colon;
  char host[INET_ADDRSTRLEN];
  size_t hostlen;
  size_t sent = 0;
  int port;
  int sock;

  colon = strrchr(target, ':');
  if (colon == NULL)
    {
      printf("agent_camera: tcp=%s needs <ip>:<port>\n", target);
      return -EINVAL;
    }

  hostlen = (size_t)(colon - target);
  if (hostlen == 0 || hostlen >= sizeof(host))
    {
      printf("agent_camera: tcp=%s has an unusable address\n", target);
      return -EINVAL;
    }

  memcpy(host, target, hostlen);
  host[hostlen] = '\0';

  port = atoi(colon + 1);
  if (port <= 0 || port > 65535)
    {
      printf("agent_camera: tcp=%s has an unusable port\n", target);
      return -EINVAL;
    }

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_port = htons((uint16_t)port);

  /* Numeric addresses only.  A DNS lookup here would add a failure mode
   * (and a timeout) to a path whose whole point is to be fast, and the host
   * running the receiver is on the same LAN by construction.
   */

  if (inet_pton(AF_INET, host, &addr.sin_addr) != 1)
    {
      printf("agent_camera: tcp=%s is not a numeric IPv4 address\n", host);
      return -EINVAL;
    }

  printf("agent_camera: payload len=%zu fnv1a=0x%08" PRIx32 "\n",
         len, agent_camera_fnv1a(data, len));

  sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0)
    {
      printf("agent_camera: socket failed: %d\n", errno);
      return -errno;
    }

  clock_gettime(CLOCK_MONOTONIC, &t_start);

  /* Bounded connect.  A blocking connect() to an address that is routable but
   * silently dropped -- a guest SSID with client isolation is the ordinary
   * case -- retries SYNs for far longer than the capture session lasts, and
   * because this runs inside the frame loop the whole command wedges with the
   * sensor still streaming.  Observed exactly that before this existed.
   */

  if (!agent_camera_connect_timeout(sock, &addr, TCP_CONNECT_MS))
    {
      printf("agent_camera: connect %s:%d failed: %d\n", host, port, errno);
      close(sock);
      return -errno;
    }

  while (sent < len)
    {
      size_t chunk = len - sent;
      ssize_t nsent;

      if (chunk > TCP_SEND_CHUNK)
        {
          chunk = TCP_SEND_CHUNK;
        }

      nsent = send(sock, data + sent, chunk, 0);
      if (nsent < 0)
        {
          if (errno == EINTR || errno == EAGAIN)
            {
              continue;
            }

          printf("agent_camera: send failed at %zu of %zu: %d\n",
                 sent, len, errno);
          close(sock);
          return -errno;
        }

      sent += (size_t)nsent;
    }

  /* The close is the delimiter, and it is also what flushes the last
   * segment, so its cost belongs inside the measurement.
   */

  close(sock);
  clock_gettime(CLOCK_MONOTONIC, &t_end);

  elapsed_ms = (unsigned long)
    ((t_end.tv_sec - t_start.tv_sec) * 1000 +
     (t_end.tv_nsec - t_start.tv_nsec) / 1000000);

  printf("agent_camera: sent %zu bytes to %s:%d in %lu ms\n",
         sent, host, port, elapsed_ms);

  return OK;
}

/****************************************************************************
 * Name: agent_camera_write_file
 ****************************************************************************/

static int agent_camera_write_file(const char *path,
                                   const uint8_t *data, size_t len)
{
  ssize_t nwritten;
  int fd;

  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (fd < 0)
    {
      printf("agent_camera: open %s failed: %d\n", path, errno);
      return -errno;
    }

  nwritten = write(fd, data, len);
  close(fd);

  if (nwritten < 0 || (size_t)nwritten != len)
    {
      printf("agent_camera: write %s short (%zd of %zu): %d\n",
             path, nwritten, len, errno);
      return -EIO;
    }

  printf("agent_camera: wrote %zu bytes to %s\n", len, path);
  return OK;
}

/****************************************************************************
 * Name: agent_camera_teardown
 *
 * Description:
 *   Unwinds in tool_camera.c's order: STREAMOFF, munmap, REQBUFS(0),
 *   close.  REQBUFS(0) is what releases the PSRAM the imgdata allocator
 *   handed out; skipping it leaks a buffer heap that is larger than the
 *   whole AP kernel heap.
 *
 ****************************************************************************/

static void agent_camera_teardown(struct agent_camera_s *cam)
{
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  struct v4l2_requestbuffers rel;
  uint32_t i;

  if (cam->fd < 0)
    {
      return;
    }

  if (cam->streaming)
    {
      ioctl(cam->fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
      cam->streaming = false;
    }

  for (i = 0; i < cam->nbuffers; i++)
    {
      if (cam->bufs[i] != NULL && cam->bufs[i] != MAP_FAILED)
        {
          munmap(cam->bufs[i], cam->buflen[i]);
          cam->bufs[i] = NULL;
        }
    }

  memset(&rel, 0, sizeof(rel));
  rel.count  = 0;
  rel.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  rel.memory = V4L2_MEMORY_MMAP;
  ioctl(cam->fd, VIDIOC_REQBUFS, (uintptr_t)&rel);

  close(cam->fd);
  cam->fd = -1;
  cam->nbuffers = 0;
}

/****************************************************************************
 * Name: agent_camera_capture
 *
 * Description:
 *   The capture half of tool_camera.c's camera_v4l2_capture(), with the
 *   frame count made a parameter so a single session can be watched for
 *   more than one frame.  The tool takes exactly one.
 *
 ****************************************************************************/

static int agent_camera_capture(struct agent_camera_s *cam,
                                int width, int height,
                                unsigned int count, bool negotiate,
                                const char *out_path, bool b64,
                                bool b64_all, unsigned int rec,
                                FAR const char *session,
                                FAR const char *tcp_target)
{
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  struct v4l2_requestbuffers req;
  struct v4l2_capability cap;
  struct timeval t_start;
  struct timeval t_end;
  struct timespec t_session = { 0, 0 };
  unsigned long elapsed_ms;
  FAR uint8_t **rec_frames = NULL;
  FAR size_t *rec_lens = NULL;
  unsigned int rec_stored = 0;
  unsigned int rec_every = 1;
  uint32_t chosen_fmt = 0;
  unsigned int frame;
  uint32_t i;
  int ret;

  memset(&cap, 0, sizeof(cap));
  if (ioctl(cam->fd, VIDIOC_QUERYCAP, (uintptr_t)&cap) < 0)
    {
      printf("agent_camera: VIDIOC_QUERYCAP failed: %d\n", errno);
      return -errno;
    }

  if ((cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) == 0)
    {
      printf("agent_camera: device reports no capture capability "
             "(caps=0x%08" PRIx32 ")\n", (uint32_t)cap.capabilities);
      return -ENODEV;
    }

  ret = agent_camera_set_format(cam->fd, &width, &height, negotiate,
                                &chosen_fmt);
  if (ret < 0)
    {
      return ret;
    }

  printf("agent_camera: format ");
  agent_camera_print_fourcc(chosen_fmt);
  printf(" %dx%d sizeimage=%d\n", width, height, CAM_BUF_SIZE);

  memset(&req, 0, sizeof(req));
  req.count  = g_nbufs;
  req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_MMAP;

  if (ioctl(cam->fd, VIDIOC_REQBUFS, (uintptr_t)&req) < 0)
    {
      printf("agent_camera: VIDIOC_REQBUFS failed: %d\n", errno);
      return -errno;
    }

  cam->nbuffers = req.count < CAM_MAX_BUFFERS ? req.count : CAM_MAX_BUFFERS;
  printf("agent_camera: %" PRIu32 " buffer(s) granted\n", cam->nbuffers);

  for (i = 0; i < cam->nbuffers; i++)
    {
      struct v4l2_buffer buf;

      memset(&buf, 0, sizeof(buf));
      buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index  = i;

      if (ioctl(cam->fd, VIDIOC_QUERYBUF, (uintptr_t)&buf) < 0)
        {
          printf("agent_camera: VIDIOC_QUERYBUF(%" PRIu32 ") failed: %d\n",
                 i, errno);
          return -errno;
        }

      cam->buflen[i] = buf.length;
      cam->bufs[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                          MAP_SHARED, cam->fd, buf.m.offset);
      if (cam->bufs[i] == MAP_FAILED)
        {
          cam->bufs[i] = NULL;
          printf("agent_camera: mmap(%" PRIu32 ", %zu) failed: %d\n",
                 i, cam->buflen[i], errno);
          return -errno;
        }

      printf("agent_camera: buffer[%" PRIu32 "] len=%zu at %p\n",
             i, cam->buflen[i], cam->bufs[i]);
    }

  for (i = 0; i < cam->nbuffers; i++)
    {
      struct v4l2_buffer buf;

      memset(&buf, 0, sizeof(buf));
      buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index  = i;

      if (ioctl(cam->fd, VIDIOC_QBUF, (uintptr_t)&buf) < 0)
        {
          printf("agent_camera: VIDIOC_QBUF(%" PRIu32 ") failed: %d\n",
                 i, errno);
          return -errno;
        }
    }

  if (ioctl(cam->fd, VIDIOC_STREAMON, (uintptr_t)&type) < 0)
    {
      printf("agent_camera: VIDIOC_STREAMON failed: %d\n", errno);
      return -errno;
    }

  cam->streaming = true;

  /* Wall clock across the streaming session, so the session reports the
   * frame rate it actually achieved rather than the 30fps the sensor is
   * configured for.  Note that 'b64all' prints tens of kilobytes per
   * frame down a 115200 console, which dominates everything else; take
   * the rate from a run without it.
   */

  /* Recording mode keeps the frames instead of printing them, so the
   * capture runs at the sensor's rate and the console work happens
   * afterwards.  Printing inside the loop cannot do that: one frame of
   * base64 is ~40KB, i.e. 3.5s at 115200, so every "next" frame would be
   * whatever the driver had most recently overwritten and the clip would be
   * a time lapse rather than motion.  The frames come from the heap, which
   * on this board reaches into PSRAM (6MB), so 30 x ~30KB is affordable
   * while the 300KB SRAM heap alone would not be.
   */

  if (rec > 0)
    {
      /* Keep rec frames out of the count captured, spread evenly.  Copying
       * a frame out costs more than the 33ms between frames at 640x480 --
       * both ends are non-cacheable PSRAM -- so recording every frame loses
       * the race with the DMA and most scans come back truncated (measured:
       * 2 to 11 clean out of 30).  Sampling every rec_every'th frame buys
       * that many frame times per copy, and the result is still a real
       * recording: the frames are the sensor's own, spaced by a known
       * interval, just at a lower rate than 30fps.
       */

      rec_every = count > rec ? count / rec : 1;

      rec_frames = (FAR uint8_t **)calloc(rec, sizeof(FAR uint8_t *));
      rec_lens = (FAR size_t *)calloc(rec, sizeof(size_t));
      if (rec_frames == NULL || rec_lens == NULL)
        {
          printf("agent_camera: cannot hold %u frames\n", rec);
          free(rec_frames);
          free(rec_lens);
          return -ENOMEM;
        }
    }

  gettimeofday(&t_start, NULL);

  for (frame = 0; frame < count; frame++)
    {
      struct pollfd pfd;
      struct v4l2_buffer dqbuf;
      int nready;

      pfd.fd     = cam->fd;
      pfd.events = POLLIN;

      nready = poll(&pfd, 1, CAM_TIMEOUT_MS);
      if (nready < 0)
        {
          printf("agent_camera: poll failed: %d\n", errno);
          return -errno;
        }

      if (nready == 0)
        {
          printf("agent_camera: no frame within %d ms -- the capture path "
                 "produced nothing\n", CAM_TIMEOUT_MS);
          return -ETIMEDOUT;
        }

      memset(&dqbuf, 0, sizeof(dqbuf));
      dqbuf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      dqbuf.memory = V4L2_MEMORY_MMAP;

      if (ioctl(cam->fd, VIDIOC_DQBUF, (uintptr_t)&dqbuf) < 0)
        {
          printf("agent_camera: VIDIOC_DQBUF failed: %d\n", errno);
          return -errno;
        }

      printf("agent_camera: frame %u: index=%" PRIu32
             " bytesused=%" PRIu32 " flags=0x%08" PRIx32 "\n",
             frame, (uint32_t)dqbuf.index, (uint32_t)dqbuf.bytesused,
             (uint32_t)dqbuf.flags);

      /* The metadata the upload path has to put on every frame: which
       * session it belongs to, a monotonically increasing sequence, and a
       * monotonic clock offset from the start of the session (spec 8.3's
       * X-Sequence / X-Timestamp-Ms).  Printed here rather than invented at
       * upload time so the numbers come from the same place the frame does.
       *
       * gettimeofday() is deliberately not used for the offset: the first TLS
       * handshake shoves the realtime clock from 1970 to 2026, which would
       * make every earlier timestamp nonsense.  clock_gettime(MONOTONIC) is
       * unaffected.
       */

      if (session != NULL)
        {
          struct timespec mono;

          clock_gettime(CLOCK_MONOTONIC, &mono);

          if (t_session.tv_sec == 0 && t_session.tv_nsec == 0)
            {
              t_session = mono;
            }

          printf("agent_camera: meta session=%s sequence=%u "
                 "timestamp_ms=%lu width=%d height=%d bytes=%" PRIu32 "\n",
                 session, frame + 1,
                 (unsigned long)((mono.tv_sec - t_session.tv_sec) * 1000ul +
                                 (mono.tv_nsec - t_session.tv_nsec) /
                                 1000000l),
                 width, height, (uint32_t)dqbuf.bytesused);
        }

      /* The driver completes a buffer with V4L2_BUF_FLAG_ERROR when its
       * watchdog fires rather than leaving DQBUF blocked forever (see
       * invariant 8 in docs/reference/camera.md).  Such a buffer carries no
       * usable frame, so say so instead of validating its contents.
       */

      if ((dqbuf.flags & V4L2_BUF_FLAG_ERROR) != 0)
        {
          printf("agent_camera: buffer flagged ERROR -- capture watchdog "
                 "or encoder fault, contents not usable\n");
        }
      else if (dqbuf.bytesused == 0)
        {
          printf("agent_camera: empty frame\n");
        }
      else if (dqbuf.index < cam->nbuffers)
        {
          const uint8_t *data = cam->bufs[dqbuf.index];

          /* Get the bytes out of the capture buffer *first*, before anything
           * else touches them.  agent_camera_check_jpeg() walks the whole
           * frame looking for markers, and doing that in place -- byte at a
           * time, out of non-cacheable PSRAM -- costs more than the 33ms the
           * sensor leaves between frames, so the DMA catches up and the scan
           * we then copy is already truncated.  Measured: validating first
           * gave 11 of 29 frames a clean decode, copying first gives the
           * numbers quoted in the recording section of the docs.
           */

          if (rec > 0 && rec_stored < rec && (frame % rec_every) == 0)
            {
              FAR uint8_t *copy = (FAR uint8_t *)malloc(dqbuf.bytesused);

              if (copy == NULL)
                {
                  printf("agent_camera: out of memory at frame %u, "
                         "recording %u frame(s)\n", frame, rec_stored);
                  rec = rec_stored;
                }
              else
                {
                  agent_camera_copy32(copy, data, dqbuf.bytesused);
                  rec_frames[rec_stored] = copy;
                  rec_lens[rec_stored] = dqbuf.bytesused;
                  rec_stored++;

                  /* Validate the copy, not the live buffer. */

                  data = copy;
                }
            }

          agent_camera_check_jpeg(data, dqbuf.bytesused);

          /* Deliver the *last* frame of the session, not the first.
           *
           * This used to take frame 0, which is the one frame guaranteed to
           * be affected by the startup transient: the encoder is enabled at
           * an arbitrary phase of the continuously-streaming sensor, so the
           * driver reports err=3 resets=3 on every session (camera.md
           * §14.4).  Those frames still pass the marker checks, so nothing
           * in the log says the *contents* are wrong -- and because every
           * image ever retrieved with 'b64' or 'out=' was frame 0, the
           * spliced picture that came out was mistaken for the pipeline's
           * normal output.
           *
           * With count == 1 (the default, and what ai_agent's
           * camera_capture does) this is still frame 0.  Ask for more
           * frames to step past the transient.
           */

          /* Every frame, when asked for.  This is the interface a host-side
           * recording uses: one fenced base64 block per frame, each carrying
           * its own index and length, so a burst can be reassembled into a
           * clip without a filesystem on the board.  See the file header for
           * the extraction one-liner.
           */

          if (b64_all)
            {
              printf("agent_camera: frame %u of %u\n", frame + 1, count);
              agent_camera_print_b64(data, dqbuf.bytesused);
            }

          if (tcp_target != NULL && rec == 0 &&
              (b64_all || frame + 1 == count))
            {
              agent_camera_send_tcp(tcp_target, data, dqbuf.bytesused);
            }

          if (frame + 1 == count)
            {
              if (out_path != NULL)
                {
                  agent_camera_write_file(out_path, data, dqbuf.bytesused);
                }

              if (b64 && !b64_all)
                {
                  agent_camera_print_b64(data, dqbuf.bytesused);
                }
            }
        }

      if (ioctl(cam->fd, VIDIOC_QBUF, (uintptr_t)&dqbuf) < 0)
        {
          printf("agent_camera: re-QBUF failed: %d\n", errno);
          return -errno;
        }
    }

  gettimeofday(&t_end, NULL);
  elapsed_ms = (unsigned long)((t_end.tv_sec - t_start.tv_sec) * 1000 +
                              (t_end.tv_usec - t_start.tv_usec) / 1000);

  printf("agent_camera: session %u frame(s) in %lu ms = %lu.%02lu fps%s\n",
         count, elapsed_ms,
         elapsed_ms ? (unsigned long)count * 1000ul / elapsed_ms : 0ul,
         elapsed_ms ? (unsigned long)count * 100000ul / elapsed_ms % 100ul
                    : 0ul,
         b64_all ? " (inflated by base64 output)" : "");

  if (rec_stored > 0)
    {
      unsigned int stored;

      printf("agent_camera: recording %u frame(s), 1 in every %u captured "
             "(about %lu.%02lu fps), dumping now\n",
             rec_stored, rec_every,
             elapsed_ms ? (unsigned long)rec_stored * 1000ul / elapsed_ms
                        : 0ul,
             elapsed_ms ? (unsigned long)rec_stored * 100000ul / elapsed_ms
                          % 100ul : 0ul);

      for (stored = 0; stored < rec_stored; stored++)
        {
          printf("agent_camera: frame %u of %u\n", stored + 1, rec_stored);

          /* With a TCP target the console dump is redundant and costs
           * seconds per frame, so tcp= replaces it rather than adding to it.
           * Ask for both only by passing b64 explicitly.
           */

          if (tcp_target != NULL)
            {
              agent_camera_send_tcp(tcp_target, rec_frames[stored],
                                    rec_lens[stored]);
            }

          if (tcp_target == NULL || b64)
            {
              agent_camera_print_b64(rec_frames[stored], rec_lens[stored]);
            }

          free(rec_frames[stored]);
        }

      printf("agent_camera: recording done\n");
    }

  free(rec_frames);
  free(rec_lens);

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct agent_camera_size_s sizes[MAX_ENUM_SIZES];
  struct agent_camera_s cam;
  const char *out_path = NULL;
  unsigned int count = 1;
  bool caps_only = false;
  bool auto_size = true;
  bool negotiate = true;
  bool b64 = false;
  bool b64_all = false;
  unsigned int rec = 0;
  FAR const char *session = NULL;
  FAR const char *tcp_target = NULL;
  int width = 0;
  int height = 0;
  int nsizes;
  int ret;
  int i;

  memset(&cam, 0, sizeof(cam));
  cam.fd = -1;

  for (i = 1; i < argc; i++)
    {
      const char *arg = argv[i];

      if (strcmp(arg, "auto") == 0)
        {
          auto_size = true;
        }
      else if (strcmp(arg, "low") == 0)
        {
          width     = TOOL_LOW_WIDTH;
          height    = TOOL_LOW_HEIGHT;
          auto_size = false;
        }
      else if (strcmp(arg, "high") == 0)
        {
          width     = TOOL_HIGH_WIDTH;
          height    = TOOL_HIGH_HEIGHT;
          auto_size = false;
        }
      else if (strcmp(arg, "caps") == 0)
        {
          caps_only = true;
        }
      else if (strcmp(arg, "strict") == 0)
        {
          negotiate = false;
        }
      else if (strncmp(arg, "bufs=", 5) == 0)
        {
          unsigned long v = strtoul(arg + 5, NULL, 10);

          if (v >= 1 && v <= CAM_MAX_BUFFERS)
            {
              g_nbufs = (uint32_t)v;
            }
        }
      else if (strcmp(arg, "b64") == 0)
        {
          b64 = true;
        }
      else if (strncmp(arg, "session=", 8) == 0)
        {
          session = arg + 8;
        }
      else if (strncmp(arg, "rec=", 4) == 0)
        {
          rec = (unsigned int)atoi(arg + 4);
        }
      else if (strcmp(arg, "b64all") == 0)
        {
          b64 = true;
          b64_all = true;
        }
      else if (strncmp(arg, "out=", 4) == 0)
        {
          out_path = arg + 4;
        }
      else if (strncmp(arg, "tcp=", 4) == 0)
        {
          tcp_target = arg + 4;
        }
      else if (strncmp(arg, "n=", 2) == 0)
        {
          count = (unsigned int)strtoul(arg + 2, NULL, 10);
          if (count == 0)
            {
              count = 1;
            }
        }
      else if (strchr(arg, 'x') != NULL)
        {
          char *endp;

          width = (int)strtol(arg, &endp, 10);
          if (endp == NULL || *endp != 'x')
            {
              agent_camera_usage();
              return EXIT_FAILURE;
            }

          height    = (int)strtol(endp + 1, NULL, 10);
          auto_size = false;

          if (width <= 0 || height <= 0)
            {
              agent_camera_usage();
              return EXIT_FAILURE;
            }
        }
      else
        {
          agent_camera_usage();
          return EXIT_FAILURE;
        }
    }

  cam.fd = open(CAM_DEV, O_RDWR);
  if (cam.fd < 0)
    {
      printf("agent_camera: open %s failed: %d\n", CAM_DEV, errno);
      return EXIT_FAILURE;
    }

  nsizes = agent_camera_enum(cam.fd, V4L2_PIX_FMT_JPEG, sizes,
                             MAX_ENUM_SIZES, true);
  if (nsizes < 0)
    {
      close(cam.fd);
      return EXIT_FAILURE;
    }

  printf("agent_camera: driver enumerates %d JPEG size(s)\n", nsizes);

  if (caps_only)
    {
      close(cam.fd);
      return EXIT_SUCCESS;
    }

  if (auto_size)
    {
      if (nsizes == 0)
        {
          printf("agent_camera: no JPEG size enumerated -- is the JPEG "
                 "format registered by the imgsensor driver?\n");
          close(cam.fd);
          return EXIT_FAILURE;
        }

      width  = sizes[0].width;
      height = sizes[0].height;
      printf("agent_camera: auto-selected %dx%d\n", width, height);
    }
  else
    {
      bool supported = false;

      for (i = 0; i < nsizes; i++)
        {
          if (sizes[i].width == width && sizes[i].height == height)
            {
              supported = true;
              break;
            }
        }

      if (!supported)
        {
          /* Not fatal on purpose: the point of `low` and `high` is to show
           * what tool_camera.c's hardcoded request does on this board, and
           * that means letting the request reach VIDIOC_S_FMT.
           */

          printf("agent_camera: %dx%d is not enumerated by this driver; "
                 "requesting it anyway (%s)\n",
                 width, height,
                 negotiate ? "will negotiate if refused" :
                             "strict: no negotiation");
        }
    }

  ret = agent_camera_capture(&cam, width, height, count, negotiate,
                             out_path, b64, b64_all, rec, session,
                             tcp_target);
  agent_camera_teardown(&cam);

  if (ret < 0)
    {
      printf("agent_camera: FAILED (%d)\n", ret);
      return EXIT_FAILURE;
    }

  printf("agent_camera: OK\n");
  return EXIT_SUCCESS;
}
"}

{"content":"/****************************************************************************
 * app/velasight/vs_audio.c
 *
 * PCM capture and playback over the NuttX audio character devices.  See
 * include/vs_audio.h for why this exists rather than reusing
 * packages/ai_agent's audio_capture/audio_playback backends.
 *
 * Both directions use the same ioctl sequence, taken from app/audio_test
 * (itself nxrecorder's): RESERVE, CONFIGURE, GETBUFFERINFO, ALLOCBUFFER,
 * mq_open, REGISTERMQ, START, prime.  START deliberately comes before the
 * first buffer is queued; see vs_audio_capture_start() for why the reverse
 * order makes teardown unsafe.  GETBUFFERINFO is not informational --
 * the upper half latches its buffer quota from it and without it every
 * ALLOCBUFFER returns 0.
 *
 * Elapsed-time budgets here use CLOCK_MONOTONIC on purpose.  The realtime
 * clock on this board jumps from 1970 to the present the first time TLS
 * completes a handshake, which is the same trap that made the agent's LLM
 * watchdog fire spuriously; the corresponding complete target file is
 * managed at `external/packages/ai_agent/src/core/agent_loop.c`.  Only the
 * absolute deadlines handed to mq_timedreceive() are CLOCK_REALTIME, because
 * that is the clock POSIX defines for them; a jump there merely shortens one
 * poll inside a loop.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <limits.h>
#include <fcntl.h>
#include <mqueue.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <time.h>
#include <unistd.h>

#include <nuttx/audio/audio.h>
#include <nuttx/mm/iob.h>

#include <arch/chip/bk7258_psram.h>

#include "include/vs_audio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_VS_AUDIO_PLAYBACK_RING_BYTES
#  define CONFIG_VS_AUDIO_PLAYBACK_RING_BYTES 655360
#endif

#ifndef CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MS
#  define CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MS 1000
#endif

#ifndef CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MAX_MS
#  define CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MAX_MS 4000
#endif

/* How much the watermark moves after a reply.
 *
 * Up fast, down slow: a starved reply is direct evidence that the current
 * value is too low, while a clean one only says it was sufficient for that
 * length -- which a short reply proves little about.  The asymmetry is the
 * usual shape for this kind of controller.
 */

#define VS_AUDIO_PB_WATERMARK_RISE 2
#define VS_AUDIO_PB_WATERMARK_FALL_MS 100

/* Audio that must build back up before a starved DAC is un-paused.  Half a
 * second is roughly two driver queues, enough that resuming does not
 * immediately starve again on the next buffer.
 */

#define VS_AUDIO_PB_RESUME_MS 500

/* Smallest playback ring worth running with, used only if PSRAM cannot supply
 * the configured size.  Four seconds still plays, it just cannot keep the TTS
 * socket read while it does -- so it is a degraded mode to report, not a
 * silent fallback.
 */

#define VS_AUDIO_PB_RING_MIN 131072

#ifndef CONFIG_VS_AUDIO_CAPTURE_SETTLE_BUFFERS
#  define CONFIG_VS_AUDIO_CAPTURE_SETTLE_BUFFERS 8
#endif

#ifndef CONFIG_VS_AUDIO_CAPTURE_RING_BYTES
#  define CONFIG_VS_AUDIO_CAPTURE_RING_BYTES 131072
#endif

#ifndef CONFIG_VS_AUDIO_MIC_GAIN
#  define CONFIG_VS_AUDIO_MIC_GAIN 6
#endif

#ifndef CONFIG_VS_AUDIO_ADC_GAIN
#  define CONFIG_VS_AUDIO_ADC_GAIN 0x2d
#endif

/* Mirrors BK7258_AUDIOIOC_SET_CAPGAIN and its argument in
 * board/.../src/bk7258_audio_bringup.h.  Duplicated for the same reason
 * app/audio_test duplicates it: applications do not get the board's private
 * src directory on their include path, and exporting a board header into
 * apps/ to share one constant would be worse coupling.  Keep in step.
 */

#define VS_AUDIO_IOC_CAPGAIN _AUDIOIOC(201)

struct vs_audio_capgain_s
{
  uint8_t mic_gain;
  uint8_t adc_gain;
  bool    hpf;
};

/* A buffer whose peak reaches this is treated as the analog front end still
 * settling rather than as audio.  The ADC returns full-scale samples for the
 * first buffers after it is enabled; at the default minimum microphone gain
 * real speech on this board measures two orders of magnitude below full
 * scale, so saturation is an unambiguous marker.  Discarding by measurement
 * instead of by a fixed count means a short utterance does not lose its
 * opening syllables to a worst-case guess.
 */

/* A sample this close to full scale has almost certainly been clipped by
 * the analog stage rather than merely being loud.
 */

#define VS_AUDIO_CLIP_LEVEL 32000

/* How saturated a buffer must be to count as the analog front end settling
 * rather than as speech, in sixteenths: 15 means "all but one sample in
 * sixteen is pinned at full scale".
 *
 * Saturation alone cannot tell the two apart, and the cost of confusing them
 * is asymmetric.  Passing a settling buffer through costs the recognizer one
 * burst of noise, which it discards; discarding a speech buffer costs the
 * opening syllables of the utterance, which nothing can recover.  So the test
 * is deliberately hard to satisfy: the front end pins essentially every sample
 * at full scale while it settles, whereas even badly overdriven speech
 * saturates only a few percent of its samples.  Speech that clips is kept and
 * sent, distortion and all -- a clipped word can still be recognised, a
 * missing one cannot.
 */

#define VS_AUDIO_SETTLE_CLIP_NUM 15
#define VS_AUDIO_SETTLE_CLIP_DEN 16

/* CONFIG_AUDIO_NUM_BUFFERS is 4 in both board configurations; the array is
 * sized with headroom so a larger quota is clamped rather than overflowing.
 */

#define VS_AUDIO_MAX_BUFFERS 8

/* The playback thread's reclaim wait, which also paces its refill loop.  One
 * driver buffer is 64 ms of 16 kHz mono audio, so this is well inside the
 * margin needed to keep the DAC fed.
 */

#define VS_AUDIO_PB_POLL_MS 10

/* The capture reader thread's wait for the next driver buffer.  One buffer is
 * 64 ms of 16 kHz mono audio, so this returns well before the driver's queue
 * could run dry.
 */

#define VS_AUDIO_CAP_POLL_MS 20

/* How long a blocked write or a drain waits between checks. */

#define VS_AUDIO_WAIT_MS 5

/* Slack added to a drain's computed playtime before it gives up.  A drain
 * that cannot finish must not hold a conversation open indefinitely.
 */

#define VS_AUDIO_DRAIN_SLACK_MS 2000

/* Bits per sample is fixed by the FIFO ports and the driver's copy loops. */

#define VS_AUDIO_BITS 16

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct vs_audio_stream_s
{
  int      fd;
  mqd_t    mq;
  const char *mqname;
  struct ap_buffer_s *buffers[VS_AUDIO_MAX_BUFFERS];
  unsigned int nbuffers;
  unsigned int buffersize;
  bool     started;
};

struct vs_audio_cap_s
{
  struct vs_audio_stream_s s;
  pthread_mutex_t lock;
  pthread_t thread;
  bool     thread_valid;

  /* Staging ring between the driver and the consumer.
   *
   * The consumer sends each chunk to the ASR service, which is a blocking
   * TLS write.  The driver only holds CONFIG_AUDIO_NUM_BUFFERS x
   * CONFIG_AUDIO_BUFFER_NUMBYTES -- about 256 ms here -- and its ISR drops
   * samples outright once that queue is empty, without reporting anything.
   * A network write that stalled for longer therefore lost audio silently:
   * measured on this board, a 15 s window came back with 12.7 s of samples.
   * The reader thread below keeps the driver's queue serviced regardless of
   * what the consumer is doing, so a stall costs ring space instead of
   * speech.
   */

  unsigned char *ring;
  size_t   ring_size;
  size_t   head;
  size_t   tail;
  size_t   level;
  bool     ring_psram;

  /* Bytes the reader thread had to discard because the ring was full.  Zero
   * unless the consumer fell seconds behind; reported so overflow can never
   * be as invisible as the driver's own dropping was.
   */

  size_t   dropped;

  /* Remaining buffers this session may still discard as front-end settling.
   * Only saturated ones are actually dropped, so this is a ceiling rather
   * than a quota.
   */

  unsigned int settle;

  /* Level of everything captured, for vs_audio_capture_level. */

  uint64_t  sumsq;
  uint64_t  samples;
  unsigned int peak;

  /* Samples delivered at or beyond VS_AUDIO_CLIP_LEVEL.  Peak saturates at
   * 32767 and so cannot say how hard the analog stage is being overdriven;
   * this can, which is what makes CONFIG_VS_AUDIO_MIC_GAIN tunable from one
   * log line instead of by trial and error.
   */

  uint64_t  clipped;

  /* Bytes discarded as front-end settling.  Reported for the same reason
   * dropped is: this is the one place that deliberately throws captured audio
   * away, so how much it threw away must not be invisible.
   */

  size_t    settled;

  /* When input was closed, and the monotonic deadline until which the reader
   * thread still admits audio.  The ADC has already filled buffers that are
   * only waiting in the queue when the user presses 说完; slamming the gate
   * shut discarded roughly a buffer period of speech they had just finished
   * saying, which is the very tail the drain exists to keep.
   */

  bool     input_stopped;
  uint64_t input_deadline_ms;
  unsigned int bytes_per_sec;
  bool     aborted;
  bool     closing;
};

struct vs_audio_pb_s
{
  struct vs_audio_stream_s s;
  pthread_mutex_t lock;
  pthread_t thread;
  bool     thread_valid;

  /* Staging ring between the TTS producer and the DAC. */

  unsigned char *ring;
  size_t   ring_size;
  size_t   head;
  size_t   tail;
  size_t   level;
  bool     ring_psram;

  /* Buffers owned by us rather than by the driver. */

  struct ap_buffer_s *freebuf[VS_AUDIO_MAX_BUFFERS];
  unsigned int freecount;
  unsigned int inflight;

  unsigned int bytes_per_sec;

  /* Bytes that must accumulate before the DAC is fed, and whether that has
   * happened yet.  Latching rather than a running watermark: re-arming the
   * gate after every dip would turn one silence into many, and by the time the
   * ring has run dry once the audio is already late.
   */

  size_t   prebuffer;
  bool     flowing;

  /* When the first byte was written, and how long the gate may hold after
   * that.  The level alone is not a sufficient release condition: a reply
   * smaller than the mark would never reach it, and would then depend entirely
   * on drain() -- which the caller only reaches once the network stream has
   * ended, seconds after the audio arrived.
   */

  uint64_t first_write_ms;
  unsigned int prebuffer_ms;

  /* Set by drain(): no more audio is coming.  An empty pipeline after this is
   * the reply finishing, not the producer falling behind, and counting it as an
   * underrun reported a gap on every single reply.
   */

  bool     producer_done;

  /* DAC muted and its transmit interrupt disabled because the ring ran dry.
   * Buffers may still be queued while this is set: the driver's
   * enqueuebuffer() only re-arms the interrupt when it is not paused, so the
   * queue simply waits rather than playing into a gap.
   */

  bool     paused;

  /* Bytes that must accumulate before un-pausing. */

  size_t   resume_level;

  /* Lowest number of network buffers seen free while this reply was arriving.
   *
   * Sampled from the TTS receive callback, which is exactly when the pool is
   * under pressure.  A 16 KB TLS record needs eleven of them and cannot be
   * decrypted until all eleven have arrived, so a figure close to zero means
   * the sender's window is being held shut by this device rather than by the
   * link -- which is indistinguishable from a slow network in every other
   * measurement available here.
   */

  int      iob_min;

  /* Times the DAC held nothing while playback was live.  Each is a gap the
   * listener heard, which is otherwise invisible -- the driver treats an empty
   * queue as silence, not as an error.
   */

  unsigned int underruns;
  bool     starved;

  bool     stopped;
  bool     closing;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Carried across playback sessions on purpose.  Each reply opens a fresh
 * handle, so a per-handle watermark would relearn the link's behaviour from
 * scratch every sentence and starve the first one every time.
 */

static unsigned int g_pb_watermark_ms =
  CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MS;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Raise a buffer-moving thread above the UI.
 *
 * Both of these run briefly and often -- one driver buffer is 64 ms of audio,
 * and the queue is four of them -- so what they need is to be scheduled
 * promptly rather than for long.  Inheriting the creator's priority put them
 * behind frame pushes, which is how a 256 ms queue runs dry.
 *
 * Failure is not fatal: the thread still works at the inherited priority, it
 * is just easier to starve, so this reports and continues.
 */

static void vs_audio_thread_priority(pthread_attr_t *attr)
{
  struct sched_param param;
  int ret;

  param.sched_priority = VS_PRIORITY_AUDIO;
  ret = pthread_attr_setschedparam(attr, &param);
  if (ret == 0)
    {
      ret = pthread_attr_setschedpolicy(attr, SCHED_FIFO);
    }

  if (ret != 0)
    {
      printf("vs_audio: thread priority %d rejected: %d\n",
             VS_PRIORITY_AUDIO, ret);
    }
}

static uint64_t vs_audio_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0)
    {
      return 0;
    }

  return (uint64_t)ts.tv_sec * 1000u + (uint64_t)(ts.tv_nsec / 1000000);
}

static int vs_audio_realtime_deadline(struct timespec *ts, unsigned int ms)
{
  if (clock_gettime(CLOCK_REALTIME, ts) < 0)
    {
      return -errno;
    }

  ts->tv_nsec += (long)(ms % 1000u) * 1000000L;
  ts->tv_sec  += (time_t)(ms / 1000u);
  if (ts->tv_nsec >= 1000000000L)
    {
      ts->tv_nsec -= 1000000000L;
      ts->tv_sec++;
    }

  return 0;
}

/* Peak absolute amplitude of one buffer, used both to recognise a settling
 * buffer and to report the delivered level.
 */

static unsigned int vs_audio_peak(const int16_t *samples, size_t count,
                                  size_t *clipped)
{
  unsigned int peak = 0;
  size_t hits = 0;
  size_t i;

  for (i = 0; i < count; i++)
    {
      int32_t v = samples[i];
      unsigned int mag = (unsigned int)(v < 0 ? -v : v);

      if (mag > peak)
        {
          peak = mag;
        }

      if (mag >= VS_AUDIO_CLIP_LEVEL)
        {
          hits++;
        }
    }

  if (clipped != NULL)
    {
      *clipped = hits;
    }

  return peak;
}

/* Caller holds the lock.  Accumulated over delivered samples only, so
 * discarded settling buffers cannot flatter the reported level.
 */

static void vs_audio_level_add(struct vs_audio_cap_s *cap,
                               const int16_t *samples, size_t count)
{
  size_t clipped = 0;
  unsigned int peak = vs_audio_peak(samples, count, &clipped);
  size_t i;

  if (peak > cap->peak)
    {
      cap->peak = peak;
    }

  cap->clipped += clipped;

  for (i = 0; i < count; i++)
    {
      int32_t v = samples[i];

      cap->sumsq += (uint64_t)((int64_t)v * v);
    }

  cap->samples += count;
}

static bool vs_audio_params_valid(unsigned int sample_rate,
                                  unsigned int channels, unsigned int bits)
{
  /* Only the rates reachable from the 26 MHz crystal.  24000 is accepted by
   * aud_set_dac_samplerate() but belongs to the 48 kHz family, which needs
   * the APLL sequence aud_clk_config() rejects, so it would play at the
   * wrong pitch instead of failing.  Refuse it here where it is still a
   * diagnosable error.
   */

  if (sample_rate != 8000 && sample_rate != 16000 && sample_rate != 32000)
    {
      printf("vs_audio: sample rate %u unsupported (8000/16000/32000)\n",
             sample_rate);
      return false;
    }

  if (bits != VS_AUDIO_BITS)
    {
      printf("vs_audio: %u-bit samples unsupported (16 only)\n", bits);
      return false;
    }

  if (channels == 0 || channels > 2)
    {
      printf("vs_audio: %u channel(s) unsupported\n", channels);
      return false;
    }

  return true;
}

static int vs_audio_enqueue(struct vs_audio_stream_s *s,
                            struct ap_buffer_s *apb)
{
  struct audio_buf_desc_s desc;

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = apb->nbytes;
  desc.u.buffer = apb;

  if (ioctl(s->fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&desc) < 0)
    {
      return -errno;
    }

  return 0;
}

static void vs_audio_stream_close(struct vs_audio_stream_s *s)
{
  struct audio_buf_desc_s desc;
  unsigned int i;

  if (s->fd < 0)
    {
      return;
    }

  if (s->started)
    {
      (void)ioctl(s->fd, AUDIOIOC_STOP, 0);
      s->started = false;
    }

  if (s->mq != (mqd_t)-1)
    {
      (void)ioctl(s->fd, AUDIOIOC_UNREGISTERMQ, (unsigned long)s->mq);
    }

  for (i = 0; i < s->nbuffers; i++)
    {
      if (s->buffers[i] != NULL)
        {
          memset(&desc, 0, sizeof(desc));
          desc.u.buffer = s->buffers[i];
          (void)ioctl(s->fd, AUDIOIOC_FREEBUFFER, (unsigned long)&desc);
          s->buffers[i] = NULL;
        }
    }

  (void)ioctl(s->fd, AUDIOIOC_RELEASE, 0);

  if (s->mq != (mqd_t)-1)
    {
      mq_close(s->mq);
      mq_unlink(s->mqname);
      s->mq = (mqd_t)-1;
    }

  close(s->fd);
  s->fd = -1;
}

static int vs_audio_stream_open(struct vs_audio_stream_s *s,
                                const char *dev_path, const char *mqname,
                                bool playback, unsigned int sample_rate,
                                unsigned int channels)
{
  struct audio_caps_desc_s cap_desc;
  struct ap_buffer_info_s buf_info;
  struct audio_buf_desc_s desc;
  struct mq_attr attr;
  unsigned int i;
  int ret;

  memset(s, 0, sizeof(*s));
  s->fd = -1;
  s->mq = (mqd_t)-1;
  s->mqname = mqname;

  s->fd = open(dev_path, O_RDWR | O_CLOEXEC);
  if (s->fd < 0)
    {
      ret = -errno;
      printf("vs_audio: cannot open %s: %d\n", dev_path, ret);
      return ret;
    }

  if (ioctl(s->fd, AUDIOIOC_RESERVE, 0) < 0)
    {
      ret = -errno;
      printf("vs_audio: RESERVE failed on %s: %d\n", dev_path, ret);
      goto err;
    }

  /* Gain staging must precede CONFIGURE: that is where the driver runs
   * adc_setup() and latches these into the analog front end.  The analog
   * stage sits ahead of the ADC, so it is the only one that changes the
   * signal-to-noise ratio -- but it also clips transients irrecoverably if
   * pushed too far, which is why this is configurable rather than maximal.
   */

  if (!playback)
    {
      struct vs_audio_capgain_s gain;

      gain.mic_gain = (uint8_t)CONFIG_VS_AUDIO_MIC_GAIN;
      gain.adc_gain = (uint8_t)CONFIG_VS_AUDIO_ADC_GAIN;
      gain.hpf = false;

      if (ioctl(s->fd, VS_AUDIO_IOC_CAPGAIN, (unsigned long)&gain) < 0)
        {
          /* Not fatal: the driver's own defaults still record, just quieter.
           * Report it once so a level problem is not mistaken for one.
           */

          printf("vs_audio: capture gain request rejected: %d\n", -errno);
        }
    }

  /* PCM format.  The sample rate is split across hw[0] and b[3] because that
   * is how nxplayer sends it and how the lower half recombines it.
   */

  memset(&cap_desc, 0, sizeof(cap_desc));
  cap_desc.caps.ac_len = sizeof(struct audio_caps_s);
  cap_desc.caps.ac_type = playback ? AUDIO_TYPE_OUTPUT : AUDIO_TYPE_INPUT;
  cap_desc.caps.ac_channels = (uint8_t)channels;
  cap_desc.caps.ac_controls.hw[0] = (uint16_t)(sample_rate & 0xffff);
  cap_desc.caps.ac_controls.b[3] = (uint8_t)(sample_rate >> 16);
  cap_desc.caps.ac_controls.b[2] = VS_AUDIO_BITS;
  cap_desc.caps.ac_subtype = AUDIO_FMT_PCM;

  if (ioctl(s->fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc) < 0)
    {
      ret = -errno;
      printf("vs_audio: CONFIGURE failed on %s: %d (%u Hz, %u channel(s))\n",
             dev_path, ret, sample_rate, channels);
      goto err;
    }

  if (ioctl(s->fd, AUDIOIOC_GETBUFFERINFO, (unsigned long)&buf_info) < 0)
    {
      ret = -errno;
      printf("vs_audio: GETBUFFERINFO failed on %s: %d\n", dev_path, ret);
      goto err;
    }

  s->buffersize = buf_info.buffer_size;
  s->nbuffers = buf_info.nbuffers;
  if (s->nbuffers > VS_AUDIO_MAX_BUFFERS)
    {
      s->nbuffers = VS_AUDIO_MAX_BUFFERS;
    }

  if (s->nbuffers == 0 || s->buffersize < sizeof(int16_t))
    {
      printf("vs_audio: driver offered %u buffer(s) of %u byte(s)\n",
             s->nbuffers, s->buffersize);
      ret = -EIO;
      goto err;
    }

  for (i = 0; i < s->nbuffers; i++)
    {
      memset(&desc, 0, sizeof(desc));
      desc.numbytes = s->buffersize;
      desc.u.pbuffer = &s->buffers[i];

      /* A return of 0 is not success: the upper half uses it to report that
       * its buffer quota is already exhausted.
       */

      ret = ioctl(s->fd, AUDIOIOC_ALLOCBUFFER, (unsigned long)&desc);
      if (ret <= 0 || s->buffers[i] == NULL)
        {
          printf("vs_audio: ALLOCBUFFER %u of %u returned %d\n", i,
                 s->nbuffers, ret);
          s->buffers[i] = NULL;
          s->nbuffers = i;
          ret = -ENOMEM;
          goto err;
        }
    }

  /* Drop any queue left behind by an earlier session so stale completions
   * cannot be mistaken for this session's buffers.
   */

  (void)mq_unlink(mqname);

  attr.mq_maxmsg = s->nbuffers + 8;
  attr.mq_msgsize = sizeof(struct audio_msg_s);
  attr.mq_curmsgs = 0;
  attr.mq_flags = 0;

  s->mq = mq_open(mqname, O_RDWR | O_CREAT, 0644, &attr);
  if (s->mq == (mqd_t)-1)
    {
      ret = -errno;
      printf("vs_audio: mq_open(%s) failed: %d\n", mqname, ret);
      goto err;
    }

  if (ioctl(s->fd, AUDIOIOC_REGISTERMQ, (unsigned long)s->mq) < 0)
    {
      ret = -errno;
      printf("vs_audio: REGISTERMQ failed on %s: %d\n", dev_path, ret);
      goto err;
    }

  return 0;

err:
  vs_audio_stream_close(s);
  return ret;
}

/****************************************************************************
 * Private Functions -- capture
 ****************************************************************************/

/* Append one driver buffer's samples to the ring.  Caller holds the lock.
 * Returns the number of bytes that did not fit.
 */

static size_t vs_audio_ring_put(struct vs_audio_cap_s *cap,
                                const unsigned char *src, size_t len)
{
  size_t room = cap->ring_size - cap->level;
  size_t take = len < room ? len : room;
  size_t first;

  if (take == 0)
    {
      return len;
    }

  first = cap->ring_size - cap->head;
  if (first > take)
    {
      first = take;
    }

  memcpy(cap->ring + cap->head, src, first);
  if (first < take)
    {
      memcpy(cap->ring, src + first, take - first);
    }

  cap->head = (cap->head + take) % cap->ring_size;
  cap->level += take;
  return len - take;
}

/* Keep the driver's queue serviced no matter how long the consumer spends in
 * the network, and stage what arrives in the ring.
 */

static void *vs_audio_cap_thread(void *arg)
{
  struct vs_audio_cap_s *cap = arg;

  for (; ; )
    {
      struct audio_msg_s msg;
      struct timespec ts;
      struct ap_buffer_s *apb;
      unsigned int prio;
      ssize_t got;
      bool done;

      if (vs_audio_realtime_deadline(&ts, VS_AUDIO_CAP_POLL_MS) < 0)
        {
          usleep(VS_AUDIO_CAP_POLL_MS * 1000);
        }
      else
        {
          got = mq_timedreceive(cap->s.mq, (char *)&msg, sizeof(msg), &prio,
                                &ts);
          if (got == (ssize_t)sizeof(msg))
            {
              if (msg.msg_id == AUDIO_MSG_IOERR)
                {
                  printf("vs_audio: capture reported an I/O error\n");
                }
              else if (msg.msg_id == AUDIO_MSG_DEQUEUE && msg.u.ptr != NULL)
                {
                  apb = msg.u.ptr;

                  pthread_mutex_lock(&cap->lock);

                  /* Drop the saturated buffers the analog front end emits
                   * while the ADC settles.  Settling is detected rather than
                   * assumed: the first buffer that is not saturated ends the
                   * discard phase and is kept, so an utterance keeps its
                   * opening syllables even when the user starts talking
                   * immediately.  The configured count only bounds how long
                   * this can go on.
                   */

                  if (apb->nbytes >= sizeof(int16_t) && cap->settle > 0)
                    {
                      size_t total = apb->nbytes / sizeof(int16_t);
                      size_t clipped = 0;

                      (void)vs_audio_peak((const int16_t *)apb->samp, total,
                                          &clipped);

                      if (clipped * VS_AUDIO_SETTLE_CLIP_DEN >
                          total * VS_AUDIO_SETTLE_CLIP_NUM)
                        {
                          cap->settle--;
                          cap->settled += apb->nbytes;
                          apb->nbytes = 0;
                        }
                      else
                        {
                          cap->settle = 0;
                        }
                    }

                  if (apb->nbytes >= sizeof(int16_t) && !cap->aborted &&
                      (!cap->input_stopped ||
                       vs_audio_now_ms() < cap->input_deadline_ms))
                    {
                      size_t usable = apb->nbytes &
                                      ~(size_t)(sizeof(int16_t) - 1);

                      vs_audio_level_add(cap, (const int16_t *)apb->samp,
                                         usable / sizeof(int16_t));
                      cap->dropped += vs_audio_ring_put(cap, apb->samp,
                                                        usable);
                    }

                  done = cap->closing;
                  apb->nbytes = 0;
                  apb->curbyte = 0;
                  if (!done)
                    {
                      (void)vs_audio_enqueue(&cap->s, apb);
                    }

                  pthread_mutex_unlock(&cap->lock);
                }
            }
        }

      pthread_mutex_lock(&cap->lock);
      done = cap->closing;
      pthread_mutex_unlock(&cap->lock);
      if (done)
        {
          break;
        }
    }

  return NULL;
}

/****************************************************************************
 * Public Functions -- capture
 ****************************************************************************/

struct vs_audio_cap_s *vs_audio_capture_open(const char *dev_path,
                                             unsigned int sample_rate,
                                             unsigned int channels,
                                             unsigned int bits)
{
  struct vs_audio_cap_s *cap;
  int ret;

  if (dev_path == NULL ||
      !vs_audio_params_valid(sample_rate, channels, bits))
    {
      return NULL;
    }

  cap = calloc(1, sizeof(*cap));
  if (cap == NULL)
    {
      return NULL;
    }

  ret = pthread_mutex_init(&cap->lock, NULL);
  if (ret != 0)
    {
      free(cap);
      return NULL;
    }

  /* PSRAM first, for the same reason the playback ring uses it: this buffer
   * is touched at audio rate, not memory rate, and taking it out of the SRAM
   * heap would compete with the driver's own pipeline buffers.
   */

  /* Whole samples only.  Every quantity in the ring arithmetic is even --
   * the ISR advances nbytes by sizeof(int16_t), reads round down -- so an odd
   * size would, on the first overflow, leave level permanently odd: read()
   * would round its copy to zero while pending() still reported a byte, and
   * capture would stop dead from that point.  The Kconfig range does not
   * exclude odd values, so clamp here instead of trusting it.
   */

  cap->ring_size = CONFIG_VS_AUDIO_CAPTURE_RING_BYTES &
                   ~(size_t)(sizeof(int16_t) - 1);
  cap->ring = bk7258_psram_malloc(cap->ring_size);
  cap->ring_psram = cap->ring != NULL;
  if (cap->ring == NULL)
    {
      cap->ring = malloc(cap->ring_size);
    }

  if (cap->ring == NULL)
    {
      pthread_mutex_destroy(&cap->lock);
      free(cap);
      return NULL;
    }

  ret = vs_audio_stream_open(&cap->s, dev_path, "vs_aud_c", false,
                             sample_rate, channels);
  if (ret < 0)
    {
      if (cap->ring_psram)
        {
          bk7258_psram_free(cap->ring);
        }
      else
        {
          free(cap->ring);
        }

      pthread_mutex_destroy(&cap->lock);
      free(cap);
      return NULL;
    }

  cap->settle = CONFIG_VS_AUDIO_CAPTURE_SETTLE_BUFFERS;
  cap->bytes_per_sec = sample_rate * channels * (VS_AUDIO_BITS / 8);
  return cap;
}

int vs_audio_capture_start(struct vs_audio_cap_s *cap)
{
  pthread_attr_t attr;
  unsigned int i;
  int ret;

  if (cap == NULL)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&cap->lock);
  if (cap->s.started)
    {
      pthread_mutex_unlock(&cap->lock);
      return 0;
    }

  /* START before queueing anything, even though it costs the samples of the
   * first FIFO interrupt.
   *
   * A buffer must never sit in the driver's queue while the device is merely
   * PREPARED: audio_stop() in nuttx/audio/audio.c only descends to the lower
   * half from RUNNING or PAUSED, so in that state AUDIOIOC_STOP does not run
   * bk7258_audio_flush() and the buffers are never handed back.  Freeing them
   * anyway -- which is what teardown must then do -- leaves the driver's
   * pendq pointing at released memory, and close(fd) walks it.
   *
   * Nothing is lost by this order: the ISR masks its own interrupt when it
   * finds no buffer, and bk7258_audio_enqueuebuffer() re-arms it while
   * running, so the queue below picks the stream straight back up.
   */

  if (ioctl(cap->s.fd, AUDIOIOC_START, 0) < 0)
    {
      ret = -errno;
      printf("vs_audio: capture START failed: %d\n", ret);
      pthread_mutex_unlock(&cap->lock);
      return ret;
    }

  cap->s.started = true;

  for (i = 0; i < cap->s.nbuffers; i++)
    {
      cap->s.buffers[i]->nbytes = 0;
      cap->s.buffers[i]->curbyte = 0;
      ret = vs_audio_enqueue(&cap->s, cap->s.buffers[i]);
      if (ret < 0)
        {
          printf("vs_audio: capture ENQUEUEBUFFER failed: %d\n", ret);
          pthread_mutex_unlock(&cap->lock);
          return ret;
        }
    }

  pthread_mutex_unlock(&cap->lock);

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  vs_audio_thread_priority(&attr);
  ret = pthread_create(&cap->thread, &attr, vs_audio_cap_thread, cap);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      printf("vs_audio: capture thread failed: %d\n", ret);
      return -ret;
    }

  cap->thread_valid = true;
  return 0;
}

int vs_audio_capture_read(struct vs_audio_cap_s *cap, void *buf, size_t len)
{
  size_t copy;
  size_t first;

  if (cap == NULL || buf == NULL || len < sizeof(int16_t))
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&cap->lock);
  if (cap->aborted)
    {
      pthread_mutex_unlock(&cap->lock);
      return -ECANCELED;
    }

  copy = cap->level < len ? cap->level : len;

  /* Whole samples only: the caller casts this to int16_t. */

  copy &= ~(size_t)(sizeof(int16_t) - 1);
  if (copy == 0)
    {
      pthread_mutex_unlock(&cap->lock);
      return -EAGAIN;
    }

  first = cap->ring_size - cap->tail;
  if (first > copy)
    {
      first = copy;
    }

  memcpy(buf, cap->ring + cap->tail, first);
  if (first < copy)
    {
      memcpy((unsigned char *)buf + first, cap->ring, copy - first);
    }

  cap->tail = (cap->tail + copy) % cap->ring_size;
  cap->level -= copy;
  pthread_mutex_unlock(&cap->lock);
  return (int)copy;
}

size_t vs_audio_capture_pending(struct vs_audio_cap_s *cap)
{
  size_t pending;

  if (cap == NULL)
    {
      return 0;
    }

  pthread_mutex_lock(&cap->lock);
  pending = cap->level;
  pthread_mutex_unlock(&cap->lock);
  return pending;
}

void vs_audio_capture_stop(struct vs_audio_cap_s *cap)
{
  if (cap == NULL)
    {
      return;
    }

  pthread_mutex_lock(&cap->lock);
  if (!cap->input_stopped)
    {
      unsigned int rate = cap->bytes_per_sec > 0 ?
                          cap->bytes_per_sec : 32000u;

      cap->input_stopped = true;

      /* Two buffer periods of grace, computed from the geometry the driver
       * reported rather than assumed.  The ADC is part-way through a buffer
       * when this is called and the driver only hands one back once it is
       * full, so a single period races with the very arrival it is waiting
       * for; two lands it reliably and still costs only about 128 ms.  A
       * constant bound is what keeps a drain loop terminating.
       */

      cap->input_deadline_ms = vs_audio_now_ms() +
                               2u * (uint64_t)cap->s.buffersize * 1000u /
                               rate;
    }

  pthread_mutex_unlock(&cap->lock);
}

bool vs_audio_capture_input_pending(struct vs_audio_cap_s *cap)
{
  bool pending;

  if (cap == NULL)
    {
      return false;
    }

  pthread_mutex_lock(&cap->lock);
  pending = !cap->aborted &&
            (!cap->input_stopped ||
             vs_audio_now_ms() < cap->input_deadline_ms);
  pthread_mutex_unlock(&cap->lock);
  return pending;
}

void vs_audio_capture_level(struct vs_audio_cap_s *cap,
                            struct vs_audio_level_s *level)
{
  if (level == NULL)
    {
      return;
    }

  memset(level, 0, sizeof(*level));

  if (cap != NULL)
    {
      pthread_mutex_lock(&cap->lock);
      level->peak = cap->peak;
      level->dropped = cap->dropped;
      level->clipped = cap->clipped;
      level->samples = cap->samples;
      level->settled = cap->settled;
      if (cap->samples > 0)
        {
          uint64_t mean = cap->sumsq / cap->samples;
          unsigned int root = 0;
          unsigned int bit;

          /* Integer square root; this runs once per utterance, and pulling in
           * the floating-point library for it is not worth the code size.
           */

          for (bit = 1u << 15; bit > 0; bit >>= 1)
            {
              unsigned int trial = root | bit;

              if ((uint64_t)trial * trial <= mean)
                {
                  root = trial;
                }
            }

          level->rms = root;
        }

      pthread_mutex_unlock(&cap->lock);
    }
}

void vs_audio_capture_abort(struct vs_audio_cap_s *cap)
{
  if (cap == NULL)
    {
      return;
    }

  pthread_mutex_lock(&cap->lock);
  cap->aborted = true;
  cap->input_stopped = true;
  cap->level = 0;
  cap->head = 0;
  cap->tail = 0;
  pthread_mutex_unlock(&cap->lock);
}

void vs_audio_capture_close(struct vs_audio_cap_s *cap)
{
  if (cap == NULL)
    {
      return;
    }

  pthread_mutex_lock(&cap->lock);
  cap->closing = true;
  pthread_mutex_unlock(&cap->lock);

  if (cap->thread_valid)
    {
      pthread_join(cap->thread, NULL);
      cap->thread_valid = false;
    }

  vs_audio_stream_close(&cap->s);

  if (cap->ring_psram)
    {
      bk7258_psram_free(cap->ring);
    }
  else
    {
      free(cap->ring);
    }

  pthread_mutex_destroy(&cap->lock);
  free(cap);
}

/****************************************************************************
 * Private Functions -- playback
 ****************************************************************************/

/* Copy out of the ring into one driver buffer.  Caller holds the lock. */

static size_t vs_audio_ring_take(struct vs_audio_pb_s *pb,
                                 struct ap_buffer_s *apb)
{
  size_t want = pb->level;
  size_t first;

  if (want > apb->nmaxbytes)
    {
      want = apb->nmaxbytes;
    }

  /* Whole samples only, or the DAC would be handed half of one. */

  want &= ~(size_t)(sizeof(int16_t) - 1);
  if (want == 0)
    {
      return 0;
    }

  first = pb->ring_size - pb->tail;
  if (first > want)
    {
      first = want;
    }

  memcpy(apb->samp, pb->ring + pb->tail, first);
  if (first < want)
    {
      memcpy(apb->samp + first, pb->ring, want - first);
    }

  pb->tail = (pb->tail + want) % pb->ring_size;
  pb->level -= want;
  return want;
}

static void *vs_audio_pb_thread(void *arg)
{
  struct vs_audio_pb_s *pb = arg;

  for (; ; )
    {
      struct audio_msg_s msg;
      struct timespec ts;
      unsigned int prio;
      ssize_t got;
      bool done;

      /* One reclaim attempt.  Its timeout is also this loop's pacing, so a
       * silent stretch does not spin.
       */

      if (vs_audio_realtime_deadline(&ts, VS_AUDIO_PB_POLL_MS) == 0)
        {
          got = mq_timedreceive(pb->s.mq, (char *)&msg, sizeof(msg), &prio,
                                &ts);
          if (got == (ssize_t)sizeof(msg) &&
              msg.msg_id == AUDIO_MSG_DEQUEUE && msg.u.ptr != NULL)
            {
              pthread_mutex_lock(&pb->lock);
              if (pb->inflight > 0)
                {
                  pb->inflight--;
                }

              if (pb->freecount < pb->s.nbuffers)
                {
                  pb->freebuf[pb->freecount++] = msg.u.ptr;
                }

              pthread_mutex_unlock(&pb->lock);
            }
        }
      else
        {
          usleep(VS_AUDIO_PB_POLL_MS * 1000);
        }

      pthread_mutex_lock(&pb->lock);

      /* Pre-roll: hold the DAC back until enough audio has accumulated, or
       * until the gate's own deadline passes.  Either release is final.
       *
       * The deadline is what makes a short reply work: it can be complete and
       * still be below the mark, in which case waiting for the mark means
       * waiting for audio that does not exist.
       */

      if (!pb->flowing &&
          (pb->level >= pb->prebuffer ||
           (pb->first_write_ms != 0 &&
            vs_audio_now_ms() - pb->first_write_ms >= pb->prebuffer_ms)))
        {
          pb->flowing = true;
        }

      /* Rebuffer: the pipeline emptied while the reply was still arriving.
       *
       * Muting and masking the transmit interrupt is not cosmetic.  Left
       * running, the DAC keeps clocking an empty FIFO and emits whatever was
       * last in it, so a gap is not silence but a held sample or a repeat.
       * Pausing makes the gap clean, and the driver still accepts buffers
       * while paused, so audio can build back up behind it.
       */

      if (pb->flowing && !pb->stopped && !pb->producer_done &&
          !pb->paused && pb->inflight == 0 && pb->level == 0)
        {
          if (ioctl(pb->s.fd, AUDIOIOC_PAUSE, 0) == 0)
            {
              pb->paused = true;
            }

          if (!pb->starved)
            {
              pb->starved = true;
              pb->underruns++;
            }
        }

      /* Resume once there is enough to keep going, or when nothing more is
       * coming -- otherwise the tail of a reply that starved right at its end
       * would never be played at all.
       */

      if (pb->paused &&
          (pb->level >= pb->resume_level || pb->producer_done ||
           pb->stopped))
        {
          if (ioctl(pb->s.fd, AUDIOIOC_RESUME, 0) == 0)
            {
              pb->paused = false;
              pb->starved = false;
            }
        }

      if (pb->level > 0 || pb->inflight > 0)
        {
          pb->starved = false;
        }

      /* Buffers are queued even while paused: they wait in the driver's queue
       * and start playing the moment it resumes, which is what makes the gap a
       * pause rather than a discontinuity.
       */

      while (pb->flowing && !pb->stopped && pb->freecount > 0 &&
             pb->level > 0)
        {
          struct ap_buffer_s *apb = pb->freebuf[pb->freecount - 1];
          size_t n;

          apb->nbytes = 0;
          apb->curbyte = 0;
          n = vs_audio_ring_take(pb, apb);
          if (n == 0)
            {
              break;
            }

          apb->nbytes = n;
          if (vs_audio_enqueue(&pb->s, apb) < 0)
            {
              /* Put the audio back so nothing is lost, and try again on the
               * next pass rather than dropping the buffer.
               */

              pb->tail = (pb->tail + pb->ring_size - n) % pb->ring_size;
              pb->level += n;
              break;
            }

          pb->freecount--;
          pb->inflight++;
        }

      done = pb->closing;
      pthread_mutex_unlock(&pb->lock);

      if (done)
        {
          break;
        }
    }

  return NULL;
}

/****************************************************************************
 * Public Functions -- output volume
 ****************************************************************************/

/* Open, set or read, close.  There is deliberately no state kept here.
 *
 * bk7258_audio_configure() stores what AUDIO_FU_VOLUME gives it in
 * priv->cfg.dac_dig_gain as well as writing the DAC gain register, precisely
 * so the setting outlives the stream that was running when it was made.  A
 * cached copy in this file could therefore only go stale, and asking the
 * driver costs one ioctl.
 */

int vs_audio_volume_set(const char *dev_path, unsigned int permille)
{
  struct audio_caps_desc_s cap_desc;
  int fd;
  int ret = 0;

  if (dev_path == NULL || permille > 1000)
    {
      return -EINVAL;
    }

  fd = open(dev_path, O_RDWR | O_CLOEXEC);
  if (fd < 0)
    {
      return -errno;
    }

  /* No RESERVE: this configures a property of the device rather than claiming
   * it, and reserving would fail while a reply is being spoken -- which is one
   * of the times a user is most likely to reach for the volume.
   */

  memset(&cap_desc, 0, sizeof(cap_desc));
  cap_desc.caps.ac_len = sizeof(struct audio_caps_s);
  cap_desc.caps.ac_type = AUDIO_TYPE_FEATURE;
  cap_desc.caps.ac_format.hw = AUDIO_FU_VOLUME;
  cap_desc.caps.ac_controls.hw[0] = (uint16_t)permille;

  if (ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc) < 0)
    {
      ret = -errno;
      printf("vs_audio: volume %u rejected: %d\n", permille, ret);
    }

  close(fd);
  return ret;
}

int vs_audio_volume_get(const char *dev_path, unsigned int *permille)
{
  struct audio_caps_desc_s cap_desc;
  int fd;
  int ret = 0;

  if (dev_path == NULL || permille == NULL)
    {
      return -EINVAL;
    }

  fd = open(dev_path, O_RDWR | O_CLOEXEC);
  if (fd < 0)
    {
      return -errno;
    }

  memset(&cap_desc, 0, sizeof(cap_desc));
  cap_desc.caps.ac_len = sizeof(struct audio_caps_s);
  cap_desc.caps.ac_type = AUDIO_TYPE_FEATURE;
  cap_desc.caps.ac_format.hw = AUDIO_FU_VOLUME;

  /* ac_channels == 0 is how the driver says it did not answer this feature,
   * which is not the same as answering zero volume.
   */

  if (ioctl(fd, AUDIOIOC_GETCAPS, (unsigned long)&cap_desc.caps) < 0)
    {
      ret = -errno;
    }
  else if (cap_desc.caps.ac_channels == 0)
    {
      ret = -ENOTTY;
    }
  else
    {
      *permille = cap_desc.caps.ac_controls.hw[0];
    }

  close(fd);
  return ret;
}

/****************************************************************************
 * Public Functions -- playback
 ****************************************************************************/

struct vs_audio_pb_s *vs_audio_playback_open(const char *dev_path,
                                             unsigned int sample_rate,
                                             unsigned int channels,
                                             unsigned int bits)
{
  struct vs_audio_pb_s *pb;
  pthread_attr_t attr;
  int ret;

  if (dev_path == NULL ||
      !vs_audio_params_valid(sample_rate, channels, bits))
    {
      return NULL;
    }

  pb = calloc(1, sizeof(*pb));
  if (pb == NULL)
    {
      return NULL;
    }

  ret = pthread_mutex_init(&pb->lock, NULL);
  if (ret != 0)
    {
      free(pb);
      return NULL;
    }

  /* PSRAM first.  This ring is touched at audio rate, not memory rate, so
   * uncached PSRAM costs it nothing, while taking 128 KiB out of the SRAM
   * heap would starve the small pipeline buffers the driver needs -- the
   * failure app/audio_test records as "ALLOCBUFFER 0 of 4".
   */

  /* Halve the request until PSRAM can satisfy it rather than failing outright.
   * The full size is what keeps a whole answer buffered, and therefore what
   * keeps the TTS socket drained, but a smaller ring still speaks -- so a
   * momentarily busy PSRAM heap should degrade playback, not cancel the reply.
   * The SRAM heap is not a fallback at these sizes; it is 336 KiB in total and
   * the driver's own pipeline buffers come out of it.
   */

  pb->ring_size = CONFIG_VS_AUDIO_PLAYBACK_RING_BYTES;
  while (pb->ring == NULL)
    {
      pb->ring = bk7258_psram_malloc(pb->ring_size);
      if (pb->ring != NULL || pb->ring_size <= VS_AUDIO_PB_RING_MIN)
        {
          break;
        }

      pb->ring_size /= 2;
    }

  pb->ring_psram = pb->ring != NULL;
  if (pb->ring == NULL)
    {
      pb->ring = malloc(pb->ring_size);
    }

  if (pb->ring == NULL)
    {
      pthread_mutex_destroy(&pb->lock);
      free(pb);
      return NULL;
    }

  if (pb->ring_size < CONFIG_VS_AUDIO_PLAYBACK_RING_BYTES)
    {
      struct bk7258_psram_info info;

      /* Not an error, and no longer a risk to the stream: since the TTS client
       * answers the server's keep-alive pings, a ring that fills only applies
       * backpressure -- the reply arrives at the speed it is spoken instead of
       * the speed of the network.  It is still worth reporting with the heap
       * figures, because the gap between what was asked for and what PSRAM
       * could give is the only clue to what else is holding the heap.
       */

      if (bk7258_psram_info(&info) == 0)
        {
          printf("vs_audio: playback ring %zu of %d byte(s); psram heap "
                 "free %zu largest %zu of %zu\n",
                 pb->ring_size, CONFIG_VS_AUDIO_PLAYBACK_RING_BYTES,
                 info.heap.free, info.heap.largest_free, info.heap.size);
        }
      else
        {
          printf("vs_audio: playback ring %zu of %d byte(s)\n",
                 pb->ring_size, CONFIG_VS_AUDIO_PLAYBACK_RING_BYTES);
        }
    }

  ret = vs_audio_stream_open(&pb->s, dev_path, "vs_aud_p", true, sample_rate,
                             channels);
  if (ret < 0)
    {
      goto err_ring;
    }

  pb->freecount = pb->s.nbuffers;
  memcpy(pb->freebuf, pb->s.buffers,
         pb->s.nbuffers * sizeof(pb->freebuf[0]));
  pb->bytes_per_sec = sample_rate * channels * (VS_AUDIO_BITS / 8);

  /* Clamped to a fraction of the ring: a pre-buffer the ring cannot hold would
   * never be satisfied, and playback would depend entirely on drain() to
   * release it.  Whole samples only, for the same reason the ring size is.
   */

  pb->prebuffer = (size_t)pb->bytes_per_sec * g_pb_watermark_ms / 1000u;
  if (pb->prebuffer > pb->ring_size / 2)
    {
      pb->prebuffer = pb->ring_size / 2;
    }

  pb->prebuffer &= ~(size_t)(sizeof(int16_t) - 1);
  pb->prebuffer_ms = g_pb_watermark_ms;
  pb->flowing = pb->prebuffer == 0;

  pb->resume_level = (size_t)pb->bytes_per_sec * VS_AUDIO_PB_RESUME_MS / 1000u;
  if (pb->resume_level > pb->ring_size / 2)
    {
      pb->resume_level = pb->ring_size / 2;
    }

  pb->resume_level &= ~(size_t)(sizeof(int16_t) - 1);
  pb->iob_min = INT_MAX;

  /* Start the DAC now, before any audio exists.
   *
   * The alternative -- queue a buffer or two first, then start -- would put
   * buffers in the driver's queue while it is still only PREPARED, and
   * AUDIOIOC_STOP does not hand those back (see the comment in
   * vs_audio_capture_start()), so teardown would free memory the driver
   * still has linked.  Starting empty is safe instead: the TX ISR masks its
   * own interrupt when it finds nothing to play and enqueuebuffer() re-arms
   * it, and the driver's own start sequence keeps the amplifier muted until
   * the analog output has settled, so an idle DAC is silent rather than
   * noisy.
   */

  if (ioctl(pb->s.fd, AUDIOIOC_START, 0) < 0)
    {
      ret = -errno;
      printf("vs_audio: playback START failed: %d\n", ret);
      vs_audio_stream_close(&pb->s);
      goto err_ring;
    }

  pb->s.started = true;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  vs_audio_thread_priority(&attr);
  ret = pthread_create(&pb->thread, &attr, vs_audio_pb_thread, pb);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      printf("vs_audio: playback thread failed: %d\n", ret);
      vs_audio_stream_close(&pb->s);
      goto err_ring;
    }

  pb->thread_valid = true;
  return pb;

err_ring:
  if (pb->ring_psram)
    {
      bk7258_psram_free(pb->ring);
    }
  else
    {
      free(pb->ring);
    }

  pthread_mutex_destroy(&pb->lock);
  free(pb);
  return NULL;
}

int vs_audio_playback_write(struct vs_audio_pb_s *pb, const void *buf,
                            size_t len)
{
  const unsigned char *src = buf;
  size_t done = 0;

  if (pb == NULL || buf == NULL)
    {
      return -EINVAL;
    }

  if (len == 0)
    {
      return 0;
    }

  while (done < len)
    {
      size_t room;
      size_t chunk;
      size_t first;

      pthread_mutex_lock(&pb->lock);
      if (pb->stopped)
        {
          pthread_mutex_unlock(&pb->lock);
          return -ECANCELED;
        }

      room = pb->ring_size - pb->level;
      if (room == 0)
        {
          /* Backpressure: the ring holds seconds of audio, so this only
           * happens when the network is well ahead of the speaker.
           */

          pthread_mutex_unlock(&pb->lock);
          usleep(VS_AUDIO_WAIT_MS * 1000);
          continue;
        }

      chunk = len - done;
      if (chunk > room)
        {
          chunk = room;
        }

      first = pb->ring_size - pb->head;
      if (first > chunk)
        {
          first = chunk;
        }

      /* Network buffer pressure, sampled where the producer actually is.
       * throttled=true asks the same question TCP read-ahead asks, so this is
       * the figure that decides whether more data may be accepted.
       */

      {
        int navail = iob_navail(true);

        if (navail < pb->iob_min)
          {
            pb->iob_min = navail;
          }
      }

      /* Start the gate's clock at the first byte, not at open(): the DAC is
       * opened before the network request goes out, and counting the TLS
       * handshake against the pre-buffer would release it before any audio had
       * arrived at all.
       */

      if (pb->first_write_ms == 0)
        {
          pb->first_write_ms = vs_audio_now_ms();
        }

      memcpy(pb->ring + pb->head, src + done, first);
      if (first < chunk)
        {
          memcpy(pb->ring, src + done + first, chunk - first);
        }

      pb->head = (pb->head + chunk) % pb->ring_size;
      pb->level += chunk;
      done += chunk;
      pthread_mutex_unlock(&pb->lock);
    }

  return (int)len;
}

void vs_audio_playback_drain(struct vs_audio_pb_s *pb)
{
  uint64_t deadline;
  size_t pending;

  if (pb == NULL)
    {
      return;
    }

  pthread_mutex_lock(&pb->lock);
  /* Whatever is in the ring at this point is all there will ever be, so the
   * gate has done its job and must not keep a short reply waiting for audio
   * that is not coming.
   */

  pb->flowing = true;
  pb->producer_done = true;

  /* Nothing further is coming, so a pause has nothing left to wait for.  The
   * thread resumes on producer_done, but doing it here as well means drain's
   * own deadline is not spent waiting for the next poll.
   */

  if (pb->paused && ioctl(pb->s.fd, AUDIOIOC_RESUME, 0) == 0)
    {
      pb->paused = false;
    }

  pending = pb->level + (size_t)pb->inflight * pb->s.buffersize;
  deadline = vs_audio_now_ms() + VS_AUDIO_DRAIN_SLACK_MS +
             (pb->bytes_per_sec > 0 ?
              (uint64_t)pending * 1000u / pb->bytes_per_sec : 0);

  /* A trailing odd byte can never become a whole sample, so it must not keep
   * this loop waiting; vs_audio_ring_take() rounds to whole samples too.
   */

  while (!pb->stopped &&
         (pb->level >= sizeof(int16_t) || pb->inflight > 0))
    {
      pthread_mutex_unlock(&pb->lock);

      if (vs_audio_now_ms() > deadline)
        {
          printf("vs_audio: playback did not drain in time\n");
          return;
        }

      usleep(VS_AUDIO_WAIT_MS * 1000);
      pthread_mutex_lock(&pb->lock);
    }

  pthread_mutex_unlock(&pb->lock);
}

void vs_audio_playback_stop(struct vs_audio_pb_s *pb)
{
  if (pb == NULL)
    {
      return;
    }

  pthread_mutex_lock(&pb->lock);
  if (!pb->stopped)
    {
      pb->stopped = true;

      /* Drop what has not reached the driver and let the driver flush what
       * has, so the speaker goes quiet now rather than after the tail.
       */

      pb->level = 0;
      pb->head = 0;
      pb->tail = 0;
      if (pb->s.started)
        {
          (void)ioctl(pb->s.fd, AUDIOIOC_STOP, 0);
          pb->s.started = false;
        }
    }

  pthread_mutex_unlock(&pb->lock);
}

unsigned int vs_audio_playback_underruns(struct vs_audio_pb_s *pb)
{
  unsigned int count;

  if (pb == NULL)
    {
      return 0;
    }

  pthread_mutex_lock(&pb->lock);
  count = pb->underruns;
  pthread_mutex_unlock(&pb->lock);
  return count;
}

/* Fold this session's outcome into the remembered watermark.
 *
 * Called from close() rather than from the thread so it happens once per
 * reply, with the final underrun count in hand.
 */

static void vs_audio_pb_adapt(struct vs_audio_pb_s *pb)
{
  unsigned int next = g_pb_watermark_ms;

  if (pb->iob_min != INT_MAX)
    {
      printf("vs_audio: network buffers low-water %d of %d\n",
             pb->iob_min, CONFIG_IOB_NBUFFERS);
    }

  if (pb->underruns != 0)
    {
      next *= VS_AUDIO_PB_WATERMARK_RISE;
      if (next > CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MAX_MS)
        {
          next = CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MAX_MS;
        }
    }
  else if (next > CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MS)
    {
      next = next > VS_AUDIO_PB_WATERMARK_FALL_MS +
             CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MS ?
             next - VS_AUDIO_PB_WATERMARK_FALL_MS :
             CONFIG_VS_AUDIO_PLAYBACK_PREBUFFER_MS;
    }

  if (next != g_pb_watermark_ms)
    {
      printf("vs_audio: playback watermark %u -> %u ms after %u underrun(s)\n",
             g_pb_watermark_ms, next, pb->underruns);
      g_pb_watermark_ms = next;
    }
}

void vs_audio_playback_close(struct vs_audio_pb_s *pb)
{
  if (pb == NULL)
    {
      return;
    }

  vs_audio_pb_adapt(pb);

  pthread_mutex_lock(&pb->lock);
  pb->closing = true;
  pthread_mutex_unlock(&pb->lock);

  if (pb->thread_valid)
    {
      pthread_join(pb->thread, NULL);
      pb->thread_valid = false;
    }

  vs_audio_stream_close(&pb->s);

  if (pb->ring_psram)
    {
      bk7258_psram_free(pb->ring);
    }
  else
    {
      free(pb->ring);
    }

  pthread_mutex_destroy(&pb->lock);
  free(pb);
}
"}

